  "about.back": "Home",
  "about.hero_subtitle": "A project born from a simple frustration — booking flights shouldn't feel like a second job.",
  "about.creator_title": "Hey, I'm Jiwan",
  "about.creator_p1": "I'm Jiwan — the travel creator behind the Himal to Horizon YouTube channel. My channel is about real travel: no sponsored hotel suites or curated perfection, just honest journeys that help Normal Joes — people like you and me — explore the world smarter and without getting ripped off.",
  "about.creator_p2": "I built this tool out of personal frustration. I was spending hours across multiple tabs trying to find the best time to fly somewhere, only to realise I was looking at the problem the wrong way. Instead of searching for a date and hoping the price is good, what if the tool told you the best window — based on how long you actually want to stay?",
  "about.creator_p3": "That became the Stay Optimizer™, and eventually, Himal to Horizon — built specifically for Normal Joes who work hard, save thoughtfully, and deserve to see the world without being fleeced by inflated fares.",
  "about.youtube_title": "The YouTube Channel",
  "about.youtube_desc": "The Himal to Horizon YouTube channel is where I share real travel experiences — raw, unfiltered, and honest. No luxury suites or curated perfection. Just genuine stories from the road that help you plan smarter and travel more confidently.",
  "about.youtube_link": "Watch on YouTube",
  "about.photo_title": "Photography",
  "about.photo_desc": "Every destination tells a story through light. I'm passionate about landscape and travel photography — from Himalayan dawn breaking over ridgelines to quiet street scenes in cities most tourists fly over. Photography is how I slow down and really see a place.",
  "about.mission_title": "The Mission",
  "about.mission_p1": "Himal to Horizon is built for what I call Normal Joes — people who work hard, save thoughtfully, and deserve to see the world without being fleeced by inflated fares or paralysed by indecision.",
  "about.pillar_1_label": "Find the best window",
  "about.pillar_1_desc": "Not just the cheapest date — the best combination of price, duration, and flexibility.",
  "about.pillar_2_label": "Travel more of the world",
  "about.pillar_2_desc": "Longer stays at better prices mean more countries, more experiences, more stories.",
  "about.pillar_3_label": "No insider knowledge needed",
  "about.pillar_3_desc": "The tools and insights built here are the ones frequent flyers already know. Now everyone has them.",
  "about.cta": "Start Exploring",
  "about.cta_footer": "No account needed · Travelpayouts-powered fares · Built with ♥ for Normal Joes",
