  "activities.klook_title": "Klook — Activities & Experiences",
  "activities.klook_desc": "The ultimate platform for booking theme parks, local guided tours, train passes, and even local SIM cards at a massive discount. Trusted by 30M+ travellers.",
  "activities.klook_cta": "Explore Klook Deals",
  "activities.tiqets_desc": "Skip-the-line passes for major museums and cultural landmarks worldwide. Instant mobile tickets — no printing, no queuing.",
  "activities.tiqets_cta": "Search Tiqets",
  "activities.visa_warn": "Don't book non-refundable tours without checking your visa requirements first.",
  "activities.visa_warn_desc": "Confirm your entry status before committing to non-refundable bookings.",
  "activities.what_to_book": "What to book in advance",
  "activities.what_to_book_desc": "Booking in advance isn't just convenient — it's often significantly cheaper. These categories sell out fast:",
  "activities.book_parks_title": "Theme parks & attractions",
  "activities.book_parks_body": "Skip-the-line passes at a discount on Klook vs. the gate price.",
  "activities.book_tours_title": "Day tours & guided excursions",
  "activities.book_tours_body": "Local guides, city food tours, and sunrise hikes regularly sell out 48–72 hours ahead.",
  "activities.book_rail_title": "Rail passes & local transport",
  "activities.book_rail_body": "Japan Rail passes, city metro cards, and bus packages are almost always cheaper when pre-purchased.",
  "activities.book_sim_title": "SIM cards & eSIMs",
  "activities.book_sim_body": "Airport SIM counters charge 2–3× more. Pre-order on Klook for instant connectivity.",
  "activities.horizon_tips": "Horizon Tips",
  "activities.checklist_title": "Pre-booking Checklist",
  "activities.checklist_1": "Check your visa status before any non-refundable booking",
  "activities.checklist_2": "Verify attraction opening hours — many close on Mondays",
  "activities.checklist_3": "Book skip-the-line passes at least 48–72 hrs ahead",
  "activities.checklist_4": "Compare Klook vs. official websites for the best price",
  "activities.checklist_5": "Save your mobile ticket offline — not all venues have Wi-Fi",
