  "hotels.title": "Horizon Stays",
  "hotels.desc": "From boutique guesthouses to premium resorts. We compare the top networks so you don't overpay for your room.",
  "hotels.tips_title": "Horizon Stays tips",
  "hotels.tip_1": "Search the same hotel on both partners — prices can differ by 10–20% even for the same room.",
  "hotels.tip_2": "Always check the cancellation policy before you confirm. Free cancellation is worth a few extra dollars.",
  "hotels.tip_3": "Agoda often shows lower net prices for Asian properties; Hotels.com rewards frequent bookers.",
  "hotels.tip_4": "Booking in local currency can sometimes be cheaper than booking in USD.",
  "hotels.agoda_title": "Agoda — Best for Asia & Beyond",
  "hotels.agoda_desc": "Consistently the lowest prices for hotels in Asia, South America, and global hubs. 2M+ properties worldwide with instant confirmation and flexible cancellations.",
  "hotels.agoda_cta": "Search Deals on Agoda",
  "hotels.hotelscom_desc": "Great for North American travel and flexible cancellation policies. Earn a free night for every 10 nights booked through the Rewards programme.",
  "hotels.hotelscom_cta": "Search Hotels.com",
  "hotels.klook_title": "Klook Hotels & Bundles",
  "hotels.klook_desc": "Perfect for travel in Asia or booking Stay + Play bundles. Klook often offers exclusive discounts when you book your room and tours together.",
  "hotels.klook_cta": "Search Hotels on Klook",
  "hotels.check_1": "Check free cancellation deadline (not just 'free cancellation')",
  "hotels.check_2": "Read recent reviews — sort by date, not score",
  "hotels.check_3": "Confirm breakfast & taxes are included in the price",
  "hotels.check_4": "Ask about early check-in if your flight arrives early",
  "cars.title": "Horizon Car Rentals",
  "cars.desc": "Skip the counter lines and hidden fees. Select one of our verified partners to find the best vehicles for your trip.",
  "cars.how_title": "How Horizon Car Rentals works",
  "cars.step_1": "Click a partner above — you'll be taken directly to their secure booking page.",
  "cars.step_2": "Search by pickup location, dates, and car type. No hidden fees added by us.",
  "cars.step_3": "Book directly with the partner. Your confirmation goes straight to you.",
  "cars.step_4": "Some links are affiliate links — we earn a small commission at no extra cost to you.",
  "cars.localrent_title": "Localrent — Best for Local Deals",
  "cars.localrent_desc": "Support local businesses and find unique vehicles with lower deposits. Often 20–40% cheaper than the big international chains — especially outside airports.",
  "cars.localrent_cta": "Search Localrent",
  "cars.klook_title": "Klook Car Rentals",
  "cars.klook_desc": "Ideal for global airport pickups and major international brands. Compare top-tier rental fleets with zero hidden fees.",
  "cars.klook_cta": "Search Cars on Klook",
  "cars.economy_title": "EconomyBookings (Best for Major Airports)",
  "cars.economy_desc": "Our top recommendation for global airport pickups. Compares all massive international brands (Hertz, Avis, Enterprise) to find the absolute lowest daily rate.",
  "cars.economy_cta": "Compare Global Rates",
  "cars.getrentacar_title": "GetRentacar (Peer-to-Peer Deals)",
  "cars.getrentacar_desc": "Rent directly from local car owners. A fantastic alternative to traditional agencies when you want unique vehicles or need to bypass strict corporate rental requirements.",
  "cars.getrentacar_cta": "Search Local Owners",
  "cars.checklist_title": "Rental checklist",
  "cars.check_1": "Bring your home driving licence + IDP if required",
  "cars.check_2": "Photograph the car before driving away",
  "cars.check_3": "Check the fuel policy (full-to-full is best)",
  "cars.check_4": "Confirm if cross-border travel is allowed",
  "insurance.title": "Horizon Shield",
  "insurance.desc": "Travel with peace of mind. Comprehensive coverage for your next adventure — from visa proof to full trip cancellation protection.",
  "insurance.badge_top_pick": "Top Pick",
  "insurance.badge_live": "Live",
  "insurance.ekta_title": "EKTA Travel Insurance",
  "insurance.ekta_desc": "Visa-compliant travel insurance for Schengen, UK, and worldwide. Instant PDF, no queuing at the embassy. Covers medical, trip cancellation, and lost baggage.",
  "insurance.ekta_cta": "Get EKTA Coverage",
  "insurance.klook_title": "Klook Travel Insurance",
  "insurance.klook_desc": "Browse single-trip and annual travel insurance plans on Klook — medical, trip cancellation, and baggage cover from a trusted global booking platform.",
  "insurance.klook_cta": "Browse insurance on Klook",
  "insurance.vc_desc": "Budget-friendly plans with 24/7 emergency assistance. Cover medical emergencies, trip interruptions, and more.",
  "insurance.vc_cta": "Compare Plans",
  "insurance.why_title": "Why travel insurance matters",
  "insurance.why_intro": "Even experienced travellers get caught out. Here's why coverage is essential:",
  "insurance.reason1_title": "Medical emergencies abroad",
  "insurance.reason1_body": "A hospital stay overseas can cost $50,000+. Insurance covers it.",
  "insurance.reason2_title": "Trip cancellation or delay",
  "insurance.reason2_body": "Flights get cancelled, plans change. Good insurance means you're not out of pocket.",
  "insurance.reason3_title": "Lost or delayed baggage",
  "insurance.reason3_body": "Airlines lose bags. Insurance reimburses essentials while you wait.",
  "insurance.tip_label": "Horizon Tip",
  "insurance.tip_body": "For Schengen visas, EKTA is the fastest way to get an embassy-accepted insurance PDF — many travellers get approved the same day.",
  "insurance.sidebar_label": "Quick Links",
  "insurance.checklist_intro": "Pre-trip checklist:",
  "insurance.check_1": "Check if your destination requires proof of insurance",
  "insurance.check_2": "Ensure your policy covers medical evacuation",
  "insurance.check_3": "Verify coverage amount meets embassy minimums",
  "insurance.check_4": "Keep your insurance PDF on your phone",
  "insurance.check_5": "Note the 24/7 emergency hotline number",
  "insurance.check_6": "Check cancellation and refund terms before purchasing",
