  "home.hero_line1": "Viaja con inteligencia.",
  "home.hero_line2": "Sin preocupaciones.",
  "home.hero_subtitle_new": "Himal to Horizon es un asesor de viajes gratuito para personas de a pie. Eliminamos la confusión de los sitios de reserva, las reglas de visado y las tarifas aéreas — para que obtengas respuestas claras, no más pestañas abiertas.",
  "home.cta_search_flights": "Buscar Vuelos",
  "home.cta_read_guides": "Leer Guías de Viaje",
  "home.offer_title": "Lo que ofrecemos",
  "home.offer_subtitle": "Todo lo que necesitas para un viaje — en un solo lugar, gratis.",
  "home.offer_flights_title": "Búsqueda de Vuelos",
  "home.offer_flights_desc": "Buscamos en Aviasales, Kiwi y Google Flights simultáneamente. Ves todas tus opciones sin abrir tres pestañas.",
