  "home.offer_guides_title": "Guías de Viaje",
  "home.offer_guides_desc": "Guías de destino expertas sobre cuándo ir, cuánto cuesta, transporte local y lo que la mayoría de guías no mencionan.",
  "home.offer_guides_cta": "Leer guías",
  "home.offer_insurance_title": "Seguro de Viaje",
  "home.offer_insurance_desc": "Protección de viaje de EKTA — cubre emergencias médicas, cancelaciones y equipaje perdido. Cotizaciones rápidas, sin jerga.",
  "home.offer_insurance_cta": "Obtener cobertura",
  "home.who_title": "A quién ayudamos",
  "home.who_subtitle": "Lo construimos para personas comunes — no para viajeros frecuentes con acceso a salones VIP.",
  "home.who_firsttimer_title": "El Viajero Primerizo",
  "home.who_firsttimer_s1": "Nunca has salido al extranjero y no sabes por dónde empezar",
  "home.who_firsttimer_s2": "Las reglas de visa, los códigos de aeropuerto y los tiempos de escala se sienten abrumadores",
  "home.who_firsttimer_s3": "Quieres saber cuánto cuestan las cosas antes de comprometerte",
  "home.who_firsttimer_sol": "Nuestras guías de destino te llevan paso a paso — sin necesidad de agente de viajes.",
  "home.who_dealhunter_title": "El Cazador de Ofertas",
  "home.who_dealhunter_s1": "Sabes adónde quieres ir pero los precios varían mucho",
  "home.who_dealhunter_s2": "Has escuchado que puedes ahorrar mucho reservando en el momento correcto",
  "home.who_dealhunter_s3": "Quieres comparar Aviasales, Kiwi y otros a la vez",
  "home.who_dealhunter_sol": "Nuestra búsqueda de vuelos consulta varios motores de reserva en un clic. Sin sesgo de afiliados — te mostramos todos.",
  "home.who_adventurer_title": "El Buscador de Aventuras",
  "home.who_adventurer_s1": "Estás planeando un trekking, un viaje por carretera o una ruta por varios países",
  "home.who_adventurer_s2": "Necesitas saber sobre visas a la llegada, cruces fronterizos o transporte en el Sudeste Asiático",
  "home.who_adventurer_s3": "Quieres información real de viaje, no anuncios de resorts",
  "home.who_adventurer_sol": "Nuestras guías cubren Nepal, Sudeste Asiático, Sudamérica y más — con logística honesta y costos reales.",
  "home.partners_title": "Socios de reserva en los que confiamos",
  "home.partners_desc": "Hemos evaluado cada socio a continuación. Cuando haces clic y reservas, ganamos una pequeña comisión de afiliado — sin costo adicional para ti. Así mantenemos el sitio gratuito.",
  "home.partner_aviasales_desc": "El mejor para búsqueda de vuelos global",
