  "home.cat_story": "Historia de Viaje",
  "footer.affiliate_notice": "Himal to Horizon es un socio afiliado de Travelpayouts. Podemos ganar una comisión en las reservas realizadas a través de nuestros enlaces.",
  "about.back": "Inicio",
  "about.hero_subtitle": "Un proyecto nacido de una frustración simple — reservar vuelos no debería sentirse como un segundo trabajo.",
  "about.creator_title": "Hola, soy Jiwan",
  "about.creator_p1": "Construí Himal to Horizon porque creo que los viajes increíbles no deben estar reservados para personas con tiempo ilimitado o un agente de viajes a la mano. La gente normal debería poder viajar como los profesionales.",
  "about.creator_p2": "La idea comenzó de forma sencilla: pasaba horas en múltiples pestañas intentando encontrar el mejor momento para volar a algún lugar, solo para darme cuenta de que estaba mirando el problema de la manera equivocada. En vez de buscar una fecha y esperar que el precio sea bueno, ¿qué tal si la herramienta te dijera la mejor ventana — basándose en cuánto tiempo realmente quieres quedarte?",
  "about.creator_p3": "Eso se convirtió en Stay Optimizer™ y, eventualmente, en Himal to Horizon.",
  "about.youtube_title": "El Canal de YouTube",
  "about.youtube_desc": "El canal de YouTube de Himal to Horizon es donde comparto experiencias de viaje reales — sin filtros, sin artificios y con honestidad. Sin suites de lujo ni perfección curada. Solo historias genuinas del camino que te ayudan a planificar mejor y viajar con más confianza.",
  "about.youtube_link": "Ver en YouTube",
  "about.photo_title": "Fotografía",
  "about.photo_desc": "Cada destino cuenta una historia a través de la luz. Me apasiona la fotografía de paisaje y de viaje — desde el amanecer himalayo sobre las crestas hasta las tranquilas escenas callejeras de ciudades que la mayoría de los turistas sobrevuelan. La fotografía es cómo me detengo y realmente veo un lugar.",
  "about.mission_title": "La Misión",
  "about.mission_p1": "Himal to Horizon está construido para lo que llamo Personas Normales — gente que trabaja duro, ahorra con cuidado y merece ver el mundo sin ser estafada por tarifas infladas ni paralizada por la indecisión.",
  "about.pillar_1_label": "Encuentra la mejor ventana",
  "about.pillar_1_desc": "No solo la fecha más barata — la mejor combinación de precio, duración y flexibilidad.",
  "about.pillar_2_label": "Viaja más por el mundo",
  "about.pillar_2_desc": "Estancias más largas a mejores precios significan más países, más experiencias, más historias.",
  "about.pillar_3_label": "Sin conocimiento privilegiado",
  "about.pillar_3_desc": "Las herramientas e información aquí son las que los viajeros frecuentes ya conocen. Ahora todos las tienen.",
  "about.cta": "Comenzar a Explorar",
  "about.cta_footer": "Sin cuenta requerida · Tarifas en vivo de Travelpayouts · Hecho con ♥ para Personas Normales",
