  "hotels.title": "Horizonte Alojamientos",
  "hotels.desc": "Desde casas de huéspedes boutique hasta resorts premium. Comparamos las principales redes para que no pagues de más por tu habitación.",
  "hotels.tips_title": "Consejos de Horizonte Alojamientos",
  "hotels.tip_1": "Busca el mismo hotel en ambos socios — los precios pueden diferir un 10–20% incluso para la misma habitación.",
  "hotels.tip_2": "Verifica siempre la política de cancelación antes de confirmar. La cancelación gratuita vale unos dólares extra.",
  "hotels.tip_3": "Agoda suele mostrar precios más bajos para propiedades asiáticas; Hotels.com premia a los viajeros frecuentes.",
  "hotels.tip_4": "Reservar en moneda local a veces puede ser más barato que en USD.",
  "hotels.agoda_title": "Agoda — Ideal para Asia y Más",
  "hotels.agoda_desc": "Constantemente los precios más bajos para hoteles en Asia, Sudamérica y centros globales. Más de 2 millones de propiedades con confirmación instantánea.",
  "hotels.agoda_cta": "Buscar Ofertas en Agoda",
  "hotels.hotelscom_desc": "Excelente para viajes en América del Norte y políticas de cancelación flexibles. Gana una noche gratis por cada 10 noches reservadas.",
  "hotels.hotelscom_cta": "Buscar en Hotels.com",
  "hotels.klook_title": "Klook Hoteles y Paquetes",
  "hotels.klook_desc": "Perfecto para viajar por Asia o reservar paquetes Estadía + Actividades. Klook suele ofrecer descuentos exclusivos cuando reservas habitación y tours juntos.",
  "hotels.klook_cta": "Buscar Hoteles en Klook",
  "hotels.check_1": "Verifica el plazo de cancelación gratuita (no solo 'cancelación gratuita')",
  "hotels.check_2": "Lee reseñas recientes — ordena por fecha, no por puntuación",
  "hotels.check_3": "Confirma que el desayuno y los impuestos están incluidos en el precio",
  "hotels.check_4": "Pregunta sobre el check-in anticipado si tu vuelo llega temprano",
  "cars.title": "Horizonte Alquiler de Coches",
  "cars.desc": "Sáltate las colas y las tarifas ocultas. Selecciona uno de nuestros socios verificados para encontrar los mejores vehículos.",
  "cars.how_title": "Cómo funciona Horizonte Alquiler de Coches",
  "cars.step_1": "Haz clic en un socio — serás llevado a su página de reserva segura.",
  "cars.step_2": "Busca por lugar de recogida, fechas y tipo de coche. Sin tarifas ocultas de nuestra parte.",
  "cars.step_3": "Reserva directamente con el socio. Tu confirmación va directamente a ti.",
  "cars.step_4": "Algunos enlaces son de afiliados — ganamos una pequeña comisión sin costo adicional.",
  "cars.localrent_title": "Localrent — Mejor para Ofertas Locales",
  "cars.localrent_desc": "Apoya negocios locales y encuentra vehículos únicos con depósitos más bajos. A menudo 20–40% más barato.",
  "cars.localrent_cta": "Buscar en Localrent",
  "cars.klook_title": "Alquiler de Autos Klook",
  "cars.klook_desc": "Ideal para aeropuertos globales y grandes marcas. Compara flotas premium sin tarifas ocultas.",
  "cars.klook_cta": "Buscar Autos en Klook",
  "cars.economy_title": "EconomyBookings (Mejor para Aeropuertos Principales)",
  "cars.economy_desc": "Nuestra principal recomendación para aeropuertos. Compara todas las grandes marcas para la tarifa diaria más baja.",
  "cars.economy_cta": "Comparar Tarifas Globales",
  "cars.getrentacar_title": "GetRentacar (Ofertas Peer-to-Peer)",
