  "flights.hop_title": "Cómo reservar un \"Horizon Hop\"",
  "flights.hop_intro": "Un Horizon Hop (también conocido como Self-Transfer) es cómo vences los algoritmos de precios de las aerolíneas reservando dos billetes separados en vez de un itinerario directo. Así se hace:",
  "flights.hop1_title": "Encuentra el Hub",
  "flights.hop1_body": "En vez de volar directamente a tu destino pequeño (ej. Valadares, Brasil), busca el hub internacional más barato cercano — como Río de Janeiro o São Paulo. Los billetes al hub suelen ser 40–60% más baratos.",
  "flights.hop2_title": "Reserva el Hopper",
  "flights.hop2_body": "Una vez que tengas el vuelo barato al hub, reserva un vuelo local o autobús separado para el tramo final. Deja al menos 3 horas entre billetes.",
  "flights.hop3_title": "Usa Kiwi",
  "flights.hop3_body": "Kiwi.com es el único buscador que junta automáticamente estos \"Horizon Hops\" desconectados. Haz clic en el enlace de Kiwi arriba y busca la insignia verde \"Self-transfer\".",
  "flights.hop_tip_label": "Consejo Horizon",
  "flights.hop_tip_body": "El riesgo de un Self-Transfer es perder la conexión — es tu responsabilidad tomar el segundo vuelo. Siempre deja 3+ horas entre billetes y asegúrate de tener seguro de viaje.",
  "flights.shield_label": "Escudo Horizon",
  "flights.insurance_label": "Seguro de Viaje",
  "flights.insurance_tip": "Los viajes Self-Transfer requieren seguro de viaje. Si pierdes tu segundo vuelo, el seguro es lo único que te salva.",
  "flights.insurance_cta": "Asegúrate con EKTA →",
