  "visa.difficulty_page_subtitle": "Todos los destinos que cubrimos, clasificados del más fácil al más difícil de solicitar.",
  "visa.difficulty_disclaimer": "Esto es un ranking de complejidad de requisitos, no una estadística de tasa de aprobación. Ninguna autoridad de inmigración publica tasas de aceptación de visas por nacionalidad, así que no afirmamos tener una. En cambio, esta puntuación se calcula a partir de lo que ya hemos investigado para cada país: cómo se solicita, cuántos documentos necesita, si realmente se requiere un certificado de antecedentes penales o una entrevista, y cuánto tiempo suele tardar el trámite. Una calificación \"difícil\" significa más papeleo y tiempo, no menos probabilidad de aprobación.",
  "visa.difficulty_loading": "Cargando ranking…",
  "visa.difficulty_error": "No se pudo cargar el ranking de dificultad. Inténtalo de nuevo.",
  "visa.free_page_title": "Países Sin Visa y con Visa a la Llegada",
  "visa.free_page_subtitle": "Todos los destinos donde un pasaporte nepalí no necesita una visa preaprobada para ingresar.",
  "visa.free_disclaimer": "Recopilado del proyecto de código abierto passport-index-dataset. Las políticas de visado cambian con frecuencia y pueden variar según las reglas exactas de nacionalidad, así que confirma la política vigente en el sitio oficial de inmigración del destino antes de reservar vuelos. ¿Buscas un país al que solicitas en línea antes de volar? Esa es la pestaña eVisa junto a esta.",
  "visa.up_to": "Hasta",
  "visa.stay_varies": "La duración de la estadía varía",
  "visa.evisa_page_title": "Países con eVisa / Visa en Línea",
  "visa.evisa_page_subtitle": "Solicita en línea antes de volar — sin visita a la embajada, sin estampilla de visa previa.",
  "visa.evisa_disclaimer": "Una eVisa no es lo mismo que una visa a la llegada — debe solicitarse y aprobarse en línea antes de viajar, generalmente con unos días de antelación. Recopilado del proyecto de código abierto passport-index-dataset; las tarifas y tiempos de procesamiento mostrados son referencias generales, así que confirma en el portal oficial de eVisa del destino antes de reservar vuelos. ¿Buscas un país para el que no necesitas solicitar nada? Esa es la pestaña Sin Visa y a la Llegada junto a esta.",
  "visa.free_category_visa_free_title": "Sin Visa",
  "visa.free_category_visa_free_blurb": "Solo muestra tu pasaporte — sin visa, sin aprobación previa, sin tarifa de entrada.",
