  "footer.affiliate_notice": "Himal to Horizon é parceiro afiliado da Travelpayouts. Podemos ganhar comissão em reservas feitas através dos nossos links.",
  "about.back": "Início",
  "about.hero_subtitle": "Um projeto nascido de uma frustração simples — reservar voos não deveria parecer um segundo emprego.",
  "about.creator_title": "Olá, sou o Jiwan",
  "about.creator_p1": "Criei o Himal to Horizon porque acredito que as viagens incríveis não devem ser reservadas para pessoas com tempo ilimitado ou um agente de viagens à disposição. As pessoas normais devem poder viajar como os profissionais.",
  "about.creator_p2": "A ideia começou de forma simples: eu passava horas em várias abas tentando encontrar o melhor momento para voar a algum lugar, apenas para perceber que estava olhando o problema da forma errada. Em vez de procurar uma data e torcer para o preço estar bom, e se a ferramenta te dissesse a melhor janela — com base em quanto tempo você realmente quer ficar?",
  "about.creator_p3": "Isso se tornou o Stay Optimizer™ e, eventualmente, Himal to Horizon.",
  "about.youtube_title": "O Canal do YouTube",
  "about.youtube_desc": "O canal do YouTube de Himal to Horizon é onde compartilho experiências de viagem reais — cruas, sem filtros e honestas. Sem suítes de luxo ou perfeição curada. Apenas histórias genuínas da estrada que te ajudam a planejar melhor e viajar com mais confiança.",
  "about.youtube_link": "Assistir no YouTube",
  "about.photo_title": "Fotografia",
  "about.photo_desc": "Cada destino conta uma história através da luz. Sou apaixonado por fotografia de paisagem e de viagem — desde o amanhecer himalaia sobre os cumes até as tranquilas cenas de rua em cidades que a maioria dos turistas sobrevoa. A fotografia é como eu desacelero e realmente vejo um lugar.",
  "about.mission_title": "A Missão",
  "about.mission_p1": "Himal to Horizon foi construído para o que chamo de Pessoas Normais — gente que trabalha duro, economiza com cuidado e merece ver o mundo sem ser lesada por tarifas infladas ou paralisada pela indecisão.",
  "about.pillar_1_label": "Encontre a melhor janela",
  "about.pillar_1_desc": "Não apenas a data mais barata — a melhor combinação de preço, duração e flexibilidade.",
  "about.pillar_2_label": "Viaje mais pelo mundo",
  "about.pillar_2_desc": "Estadias mais longas a preços melhores significam mais países, mais experiências, mais histórias.",
  "about.pillar_3_label": "Sem conhecimento privilegiado",
  "about.pillar_3_desc": "As ferramentas e insights criados aqui são os que os viajantes frequentes já conhecem. Agora todos os têm.",
  "about.cta": "Começar a Explorar",
  "about.cta_footer": "Sem conta necessária · Tarifas verificadas no Kiwi e Google · Feito com ♥ para Pessoas Normais",
