  "hotels.title": "Horizon Estadias",
  "hotels.desc": "De pousadas boutique a resorts premium. Comparamos as principais redes para você não pagar mais pela sua acomodação.",
  "hotels.tips_title": "Dicas do Horizon Estadias",
  "hotels.tip_1": "Pesquise o mesmo hotel nos dois parceiros — os preços podem diferir 10–20% para o mesmo quarto.",
  "hotels.tip_2": "Verifique sempre a política de cancelamento antes de confirmar. Cancelamento gratuito vale a pena.",
  "hotels.tip_3": "A Agoda costuma ter preços mais baixos para propriedades asiáticas; Hotels.com recompensa viajantes frequentes.",
  "hotels.tip_4": "Reservar na moeda local pode ser mais barato do que em dólares.",
  "hotels.agoda_title": "Agoda — Melhor para Ásia e Além",
  "hotels.agoda_desc": "Consistentemente os preços mais baixos para hotéis na Ásia, América do Sul e centros globais. Mais de 2 milhões de propriedades com confirmação instantânea.",
  "hotels.agoda_cta": "Buscar Ofertas no Agoda",
  "hotels.hotelscom_desc": "Ótimo para viagens na América do Norte e políticas de cancelamento flexíveis. Ganhe uma noite grátis a cada 10 noites reservadas.",
  "hotels.hotelscom_cta": "Buscar no Hotels.com",
  "hotels.klook_title": "Klook Hotéis e Pacotes",
  "hotels.klook_desc": "Perfeito para viagens na Ásia ou pacotes Ficar + Explorar. Klook frequentemente oferece descontos exclusivos ao reservar quarto e passeios juntos.",
  "hotels.klook_cta": "Buscar Hotéis no Klook",
  "hotels.check_1": "Verifique o prazo de cancelamento gratuito (não apenas 'cancelamento gratuito')",
  "hotels.check_2": "Leia avaliações recentes — ordene por data, não por pontuação",
  "hotels.check_3": "Confirme que café da manhã e impostos estão incluídos no preço",
  "hotels.check_4": "Pergunte sobre check-in antecipado se seu voo chega cedo",
  "cars.title": "Horizon Aluguel de Carros",
  "cars.desc": "Pule as filas e as taxas ocultas. Selecione um de nossos parceiros verificados para encontrar os melhores veículos.",
  "cars.how_title": "Como funciona o Horizon Aluguel de Carros",
  "cars.step_1": "Clique em um parceiro — você será levado à página de reserva segura.",
  "cars.step_2": "Pesquise por local de retirada, datas e tipo de carro. Sem taxas ocultas da nossa parte.",
  "cars.step_3": "Reserve diretamente com o parceiro. Sua confirmação vai direto para você.",
  "cars.step_4": "Alguns links são de afiliados — ganhamos uma pequena comissão sem custo adicional.",
  "cars.localrent_title": "Localrent — Melhor para Ofertas Locais",
  "cars.localrent_desc": "Apoie negócios locais e encontre veículos únicos com depósitos menores. Frequentemente 20–40% mais barato.",
  "cars.localrent_cta": "Pesquisar Localrent",
  "cars.klook_title": "Aluguel de Carros Klook",
  "cars.klook_desc": "Ideal para aeroportos globais e grandes marcas. Compare frotas premium sem taxas ocultas.",
  "cars.klook_cta": "Pesquisar Carros no Klook",
  "cars.economy_title": "EconomyBookings (Melhor para Aeroportos Principais)",
  "cars.economy_desc": "Nossa principal recomendação para aeroportos. Compara todas as grandes marcas para a menor tarifa diária.",
  "cars.economy_cta": "Comparar Tarifas Globais",
  "cars.getrentacar_title": "GetRentacar (Ofertas Peer-to-Peer)",
