  "home.hero_line1": "Voyagez plus malin.",
  "home.hero_line2": "Sans soucis.",
  "home.hero_subtitle_new": "Himal to Horizon est un conseiller de voyage gratuit pour tout le monde. Nous démêlons les sites de réservation confus, les règles de visa et les frais aériens — pour que vous obteniez des réponses claires, pas plus d'onglets.",
  "home.cta_search_flights": "Rechercher des Vols",
  "home.cta_read_guides": "Lire les Guides de Voyage",
  "home.offer_title": "Ce que nous offrons",
  "home.offer_subtitle": "Tout ce dont vous avez besoin pour un voyage — en un seul endroit, gratuitement.",
  "home.offer_flights_title": "Recherche de Vols",
  "home.offer_flights_desc": "Nous recherchons sur Aviasales, Kiwi et Google Flights simultanément. Vous voyez toutes vos options sans ouvrir trois onglets.",
  "home.offer_flights_cta": "Rechercher des vols",
  "home.offer_visa_title": "Intelligence Visa",
  "home.offer_visa_desc": "Exigences de visa instantanées pour plus de 120 paires de pays. Sachez avant de réserver si vous avez besoin d'un visa — et comment l'obtenir.",
  "home.offer_visa_cta": "Vérifier le visa",
  "home.offer_guides_title": "Guides de Voyage",
  "home.offer_guides_desc": "Guides de destination experts sur quand partir, combien ça coûte, les transports locaux et ce que la plupart des guides ne mentionnent pas.",
  "home.offer_guides_cta": "Lire les guides",
  "home.offer_insurance_title": "Assurance Voyage",
  "home.offer_insurance_desc": "Protection voyage par EKTA — couvre les urgences médicales, les annulations et les bagages perdus. Devis rapides, sans jargon.",
  "home.offer_insurance_cta": "S'assurer",
  "home.who_title": "Qui nous aidons",
  "home.who_subtitle": "Nous avons créé ceci pour les gens ordinaires — pas pour les grands voyageurs avec accès aux salons.",
  "home.who_firsttimer_title": "Le Voyageur Débutant",
  "home.who_firsttimer_s1": "Vous n'avez jamais voyagé à l'étranger et ne savez pas par où commencer",
  "home.who_firsttimer_s2": "Les règles de visa, les codes d'aéroport et les temps de transit semblent accablants",
  "home.who_firsttimer_s3": "Vous voulez savoir ce que les choses coûtent vraiment avant de vous engager",
  "home.who_firsttimer_sol": "Nos guides de destination vous guident pas à pas — sans agent de voyage.",
  "home.who_dealhunter_title": "Le Chasseur de Bons Plans",
  "home.who_dealhunter_s1": "Vous savez où vous voulez aller mais les prix varient beaucoup",
  "home.who_dealhunter_s2": "Vous avez entendu que vous pouvez économiser en réservant au bon moment",
  "home.who_dealhunter_s3": "Vous voulez comparer Aviasales, Kiwi et d'autres en même temps",
  "home.who_dealhunter_sol": "Notre recherche de vols interroge plusieurs moteurs de réservation en un clic. Sans biais d'affiliation — nous vous montrons tout.",
  "home.who_adventurer_title": "L'Aventurier",
  "home.who_adventurer_s1": "Vous planifiez un trek, un road trip ou un itinéraire multi-pays",
  "home.who_adventurer_s2": "Vous devez connaître les visas à l'arrivée, les passages frontaliers ou les transports en Asie du Sud-Est",
  "home.who_adventurer_s3": "Vous voulez de vraies infos voyage, pas des publicités de complexes",
  "home.who_adventurer_sol": "Nos guides couvrent le Népal, l'Asie du Sud-Est, l'Amérique du Sud et au-delà — avec une logistique honnête et des coûts réels.",
  "home.partners_title": "Partenaires de réservation de confiance",
  "home.partners_desc": "Nous avons vérifié chaque partenaire ci-dessous. Lorsque vous cliquez et réservez, nous gagnons une petite commission d'affiliation — sans frais supplémentaires pour vous. C'est ainsi que nous gardons le site gratuit.",
  "home.partner_aviasales_desc": "Meilleur pour la recherche de vols mondiale",
  "home.partner_kiwi_desc": "Auto-transferts & routes cachées",
  "home.partner_12go_desc": "Trains, bus & ferries en Asie",
  "home.partner_ekta_desc": "Assurance voyage pour chaque voyage",
  "home.partner_booking_desc": "Hôtels & séjours dans le monde entier",
  "home.guides_latest": "Derniers Guides de Voyage",
  "home.guides_all_link": "guides",
  "home.mobile_visa": "Intelligence Visa",
  "home.visa_hero_badge": "Intelligence Visa pour les Titulaires de Passeport Népalais",
  "home.visa_hero_title_1": "Connaissez votre visa.",
  "home.visa_hero_title_2": "Avant de réserver.",
  "home.visa_hero_subtitle": "Exigences étape par étape, frais et liens officiels pour les titulaires de passeport népalais — vérifiés auprès de sources gouvernementales et tenus à jour.",
  "home.visa_hero_cta_primary": "Vérifier Mes Exigences de Visa",
  "home.visa_hero_cta_secondary": "Voir Tout Ce Que Nous Offrons",
  "home.trust_countries": "51 pays de destination couverts",
