  "home.trust_refresh": "Actualisé chaque semaine",
  "home.offer_community_title": "Communauté de Voyageurs",
  "home.offer_community_desc": "Histoires vraies et recommandations honnêtes de voyageurs népalais — nourriture, hébergements et trésors cachés.",
  "home.offer_community_cta": "Explorer les histoires",
  "footer.contact": "Contactez-nous à",
  "footer.flights_link": "Vols",
  "home.cat_trek": "Rapport de Trek",
  "home.cat_destination": "Guide de Destination",
  "home.cat_tips": "Conseils de Voyage",
  "home.cat_story": "Récit de Voyage",
  "footer.affiliate_notice": "Himal to Horizon est partenaire affilié de Travelpayouts. Nous pouvons percevoir une commission sur les réservations effectuées via nos liens.",
  "about.back": "Accueil",
  "about.hero_subtitle": "Un projet né d'une frustration simple — réserver des vols ne devrait pas ressembler à un deuxième emploi.",
  "about.creator_title": "Bonjour, je suis Jiwan",
  "about.creator_p1": "J'ai créé Himal to Horizon parce que je crois que les voyages incroyables ne devraient pas être réservés aux personnes ayant du temps illimité ou un agent de voyage sous la main. Les gens ordinaires devraient pouvoir voyager comme des pros.",
  "about.creator_p2": "L'idée a commencé simplement : je passais des heures sur plusieurs onglets à essayer de trouver le meilleur moment pour voler quelque part, seulement pour réaliser que je regardais le problème dans le mauvais sens. Au lieu de chercher une date et d'espérer que le prix soit bon, et si l'outil vous indiquait la meilleure fenêtre — en fonction de la durée de séjour souhaitée ?",
  "about.creator_p3": "C'est ainsi qu'est né le Stay Optimizer™ et finalement Himal to Horizon.",
  "about.youtube_title": "La chaîne YouTube",
  "about.youtube_desc": "La chaîne YouTube de Himal to Horizon est l'endroit où je partage de vraies expériences de voyage — brutes, sans filtre et honnêtes. Pas de suites de luxe ni de perfection soigneusement orchestrée. Juste des histoires authentiques de la route qui vous aident à mieux planifier et voyager avec plus de confiance.",
  "about.youtube_link": "Voir sur YouTube",
  "about.photo_title": "Photographie",
  "about.photo_desc": "Chaque destination raconte une histoire à travers la lumière. Je suis passionné de photographie de paysage et de voyage — depuis l'aube himalayenne sur les crêtes jusqu'aux scènes de rue tranquilles des villes que la plupart des touristes survolent. La photographie est ma façon de ralentir et de vraiment voir un endroit.",
  "about.mission_title": "La Mission",
  "about.mission_p1": "Himal to Horizon est conçu pour ce que j'appelle les Gens Ordinaires — des personnes qui travaillent dur, économisent judicieusement et méritent de voir le monde sans être escroquées par des tarifs gonflés ou paralysées par l'indécision.",
  "about.pillar_1_label": "Trouver la meilleure fenêtre",
  "about.pillar_1_desc": "Pas seulement la date la moins chère — la meilleure combinaison de prix, de durée et de flexibilité.",
  "about.pillar_2_label": "Voyager plus dans le monde",
  "about.pillar_2_desc": "Des séjours plus longs à de meilleurs prix signifient plus de pays, plus d'expériences, plus d'histoires.",
  "about.pillar_3_label": "Pas de connaissances privilégiées",
  "about.pillar_3_desc": "Les outils et informations créés ici sont ceux que les grands voyageurs connaissent déjà. Maintenant tout le monde les a.",
  "about.cta": "Commencer à explorer",
  "about.cta_footer": "Sans compte nécessaire · Tarifs vérifiés sur Kiwi et Google · Fait avec ♥ pour les Gens Ordinaires",
  "visa.title": "Guides Visa",
  "visa.subtitle": "Informations visa simples pour les destinations populaires — sans jargon ni legalese. Vérifiez les conditions d'entrée avant de réserver.",
  "visa.disclaimer": "Les informations sont données à titre indicatif uniquement. Consultez toujours les sources officielles de l'ambassade avant de voyager.",
