  "hotels.title": "Horizon Séjours",
  "hotels.desc": "Des maisons d'hôtes boutique aux resorts premium. Nous comparons les principaux réseaux pour que vous ne surpayiez pas votre chambre.",
  "hotels.tips_title": "Conseils Horizon Séjours",
  "hotels.tip_1": "Cherchez le même hôtel chez les deux partenaires — les prix peuvent différer de 10–20% pour la même chambre.",
  "hotels.tip_2": "Vérifiez toujours la politique d'annulation avant de confirmer. L'annulation gratuite vaut quelques dollars de plus.",
  "hotels.tip_3": "Agoda affiche souvent des prix nets plus bas pour les propriétés asiatiques ; Hotels.com récompense les voyageurs fréquents.",
  "hotels.tip_4": "Réserver en devise locale peut parfois être moins cher qu'en USD.",
  "hotels.agoda_title": "Agoda — Idéal pour l'Asie et au-delà",
  "hotels.agoda_desc": "Constamment les prix les plus bas pour les hôtels en Asie, Amérique du Sud et pôles mondiaux. Plus de 2 millions de propriétés avec confirmation instantanée.",
  "hotels.agoda_cta": "Rechercher des Offres sur Agoda",
  "hotels.hotelscom_desc": "Excellent pour les voyages en Amérique du Nord et les politiques d'annulation flexibles. Gagnez une nuit gratuite pour 10 nuits réservées.",
  "hotels.hotelscom_cta": "Rechercher sur Hotels.com",
  "hotels.klook_title": "Klook Hôtels & Forfaits",
  "hotels.klook_desc": "Parfait pour voyager en Asie ou réserver des forfaits Séjour + Activités. Klook offre souvent des réductions exclusives en combinant chambre et activités.",
  "hotels.klook_cta": "Rechercher des Hôtels sur Klook",
  "hotels.check_1": "Vérifiez la date limite d'annulation gratuite (pas seulement 'annulation gratuite')",
  "hotels.check_2": "Lisez les avis récents — triez par date, pas par note",
