  "hotels.check_4": "Demandez un check-in anticipé si votre vol arrive tôt",
  "cars.title": "Horizon Location de Voitures",
  "cars.desc": "Évitez les files d'attente et les frais cachés. Sélectionnez un de nos partenaires vérifiés pour trouver les meilleurs véhicules.",
  "cars.how_title": "Comment fonctionne Horizon Location de Voitures",
  "cars.step_1": "Cliquez sur un partenaire — vous serez redirigé vers sa page de réservation sécurisée.",
  "cars.step_2": "Recherchez par lieu de prise en charge, dates et type de voiture. Aucun frais caché de notre part.",
  "cars.step_3": "Réservez directement avec le partenaire. Votre confirmation vous est envoyée directement.",
  "cars.step_4": "Certains liens sont des liens d'affiliation — nous gagnons une petite commission sans frais supplémentaires.",
  "cars.localrent_title": "Localrent — Meilleur pour les Offres Locales",
  "cars.localrent_desc": "Soutenez les entreprises locales et trouvez des véhicules uniques avec des cautions réduites. Souvent 20–40% moins cher.",
  "cars.localrent_cta": "Rechercher Localrent",
  "cars.klook_title": "Location de Voitures Klook",
  "cars.klook_desc": "Idéal pour les aéroports mondiaux et les grandes marques. Comparez les flottes premium sans frais cachés.",
  "cars.klook_cta": "Chercher Voitures sur Klook",
