  "insurance.title": "Horizon Bouclier",
  "insurance.desc": "Voyagez en toute tranquillité. Couverture complète pour votre prochaine aventure — de la preuve de visa à la protection annulation totale.",
  "insurance.badge_top_pick": "Top Pick",
