  "insurance.klook_title": "Assurance Voyage Klook",
  "insurance.klook_desc": "Parcourez les plans d'assurance voyage ponctuels et annuels sur Klook — couverture médicale, annulation de voyage et bagages, proposés par une plateforme de réservation mondiale de confiance.",
