  "activities.title": "Horizon Expériences",
  "activities.desc": "N'attendez pas dans la file d'attente. Réservez excursions, pass et transports locaux à l'avance — avec une réduction.",
  "flights.title": "Horizon Vols",
  "flights.desc": "Nos partenaires vérifiés de recherche de vols. Utilisez Kiwi pour les routes multi-villes, Google Flights pour comparer les prix.",
  "flights.trip_one_way": "Aller simple",
  "flights.trip_round_trip": "Aller-retour",
  "flights.trip_multi_city": "Multi-villes",
  "flights.form_from": "De",
