  "flights.form_optional": "opt",
  "flights.form_pick_date": "Choisir date",
  "flights.form_from_ph": "De (ex. MIA)",
  "flights.form_to_ph": "Vers (ex. KTM)",
  "flights.form_hint": "Tapez une ville ou un code IATA · les partenaires utilisent cette route",
  "flights.multi_hint": "Kiwi · Aviasales · Google prennent en charge les multi-villes",
  "flights.add_leg": "Ajouter un segment",
  "flights.remove_leg": "Supprimer le segment",
  "flights.search_aviasales": "Rechercher sur Aviasales",
  "flights.badge_self_transfer": "Auto-Correspondance",
  "flights.badge_horizons_pick": "Choix Horizon",
  "flights.badge_free": "Gratuit",
  "flights.kiwi_desc": "Idéal pour le Horizon Hop™. Le seul moteur de recherche qui construit automatiquement des itinéraires \"Self-Transfer\" — des offres multi-villes que les compagnies ne veulent pas que vous trouviez.",
  "flights.kiwi_cta": "Rechercher sur Kiwi",
  "flights.aviasales_heading": "Aviasales (Métarecherche Mondiale)",
  "flights.aviasales_desc": "Analyse des centaines de compagnies aériennes mondiales et régionales pour trouver les tarifs les plus bas.",
  "flights.aviasales_desc_multi": "Support multi-villes vérifié — analyse des centaines de compagnies sur tous vos segments pour trouver le tarif combiné le plus bas.",
  "flights.google_desc": "Le meilleur outil pour comparer les prix de base. Vérifiez que vous obtenez un prix juste avant de vous engager.",
  "flights.google_cta": "Vérifier sur Google",
  "flights.visa_heading": "Vérifiez les conditions d'entrée avant de réserver",
  "flights.visa_desc": "Vérifiez les exigences de visa pour votre passeport + destination en quelques secondes.",
  "flights.hop_title": "Comment réserver un \"Horizon Hop\"",
  "flights.hop_intro": "Un Horizon Hop (aussi appelé Self-Transfer) consiste à battre les algorithmes de prix des compagnies en réservant deux billets séparés au lieu d'un itinéraire direct. Voici comment faire :",
  "flights.hop1_title": "Trouvez le Hub",
  "flights.hop1_body": "Au lieu de voler directement vers votre petite destination (ex. Valadares, Brésil), cherchez le hub international le moins cher à proximité — comme Rio de Janeiro ou São Paulo. Les billets vers le hub sont généralement 40–60% moins chers.",
  "flights.hop2_title": "Réservez le Hopper",
  "flights.hop2_body": "Une fois le vol bon marché vers le hub sécurisé, réservez un vol local ou bus séparé pour le dernier segment. Laissez au moins 3 heures entre vos billets.",
  "flights.hop3_title": "Utilisez Kiwi",
  "flights.hop3_body": "Kiwi.com est le seul moteur de recherche qui assemble automatiquement ces \"Horizon Hops\" déconnectés. Cliquez sur le lien Kiwi ci-dessus et cherchez le badge vert \"Self-transfer\".",
  "flights.hop_tip_label": "Conseil Horizon",
  "flights.hop_tip_body": "Le risque du Self-Transfer est de rater la correspondance — c'est votre responsabilité de prendre le second vol. Prévoyez toujours 3+ heures entre les billets et assurez-vous d'avoir une assurance voyage.",
  "flights.shield_label": "Bouclier Horizon",
  "flights.insurance_label": "Assurance Voyage",
  "flights.insurance_tip": "Les voyages Self-Transfer nécessitent une assurance voyage. Si vous ratez votre second vol, l'assurance est la seule chose qui vous sauve.",
  "flights.insurance_cta": "Assurez-vous avec EKTA →",
  "flights.connectivity_label": "Connectivité",
