  "home.cat_story": "यात्रा कथा",
  "footer.affiliate_notice": "Himal to Horizon Travelpayouts को सम्बद्ध साझेदार हो। हाम्रो लिंकमार्फत गरिएको बुकिङमा हामीले कमिसन कमाउन सक्छौं।",
  "about.back": "गृहपृष्ठ",
  "about.hero_subtitle": "एक साधारण निराशाबाट जन्मिएको परियोजना — उडान बुक गर्नु दोस्रो काम जस्तो लाग्नु हुँदैन।",
  "about.creator_title": "नमस्ते, म Jiwan हुँ",
  "about.creator_p1": "मैले Himal to Horizon बनाएँ किनभने मेरो विश्वास छ कि अद्भुत यात्रा असीमित समय भएका वा ट्राभेल एजेन्ट भएकाहरूको लागि मात्र हुनु हुँदैन। सामान्य मान्छेहरू पनि पेशेवरहरू जस्तै यात्रा गर्न सक्नुपर्छ।",
  "about.creator_p2": "विचार सरलरूपमा सुरु भयो: म घण्टौं विभिन्न ट्याबहरूमा उड्नको लागि उत्तम समय खोज्दै थिएँ, अनि बुझेँ कि म समस्यालाई गलत तरिकाले हेरिरहेको थिएँ। मिति खोज्नुको साटो, के उपकरणले नै तपाईंलाई उत्तम विन्डो भन्न सक्दैन — तपाईं कति समय बस्न चाहनुहुन्छ भन्ने आधारमा?",
  "about.creator_p3": "त्यही Stay Optimizer™ बन्यो र अन्ततः Himal to Horizon।",
  "about.youtube_title": "YouTube च्यानल",
  "about.youtube_desc": "Himal to Horizon YouTube च्यानलमा म वास्तविक यात्रा अनुभवहरू साझा गर्छु — कच्चा, अनफिल्टर्ड र इमानदार। कुनै लक्जरी सुइट वा क्यूरेटेड पर्फेक्शन छैन। बस यात्राका सच्चा कथाहरू जसले तपाईंलाई स्मार्ट योजना र आत्मविश्वासका साथ यात्रा गर्न सहयोग गर्छ।",
  "about.youtube_link": "YouTube मा हेर्नुहोस्",
  "about.photo_title": "फोटोग्राफी",
  "about.photo_desc": "प्रत्येक गन्तव्यले प्रकाशमार्फत एक कथा बताउँछ। म परिदृश्य र यात्रा फोटोग्राफीमा जोशी छु — हिमालयन भोर देखि शहरका शान्त सडक दृश्यसम्म। फोटोग्राफी भनेको मेरो ढिलाइ गर्ने र साँच्चिकै ठाउँ देख्ने तरिका हो।",
  "about.mission_title": "मिसन",
  "about.mission_p1": "Himal to Horizon त्यसका लागि बनाइएको हो जसलाई म 'साधारण मान्छे' भन्छु — मेहनत गर्ने, बचत गर्ने, र फूलिएका भाडाले ठगिनु नपरी वा अनिर्णयले थलिनु नपरी संसार देख्न लायक मान्छेहरू।",
  "about.pillar_1_label": "उत्तम विन्डो खोज्नुहोस्",
  "about.pillar_1_desc": "सबैभन्दा सस्तो मिति मात्र होइन — मूल्य, अवधि र लचिलोपनको उत्तम संयोजन।",
  "about.pillar_2_label": "संसारमा बढी यात्रा गर्नुहोस्",
  "about.pillar_2_desc": "कम मूल्यमा लामो बसाइको अर्थ हो बढी देशहरू, बढी अनुभवहरू, बढी कथाहरू।",
  "about.pillar_3_label": "विशेष ज्ञान आवश्यक छैन",
  "about.pillar_3_desc": "यहाँ बनाइएका उपकरण र ज्ञान ती हुन् जुन बारम्बार उड्नेहरूलाई थाहा छ। अब सबैसँग छ।",
  "about.cta": "अन्वेषण सुरु गर्नुहोस्",
  "about.cta_footer": "खाता आवश्यक छैन · Travelpayouts लाइभ भाडाहरू · साधारण मान्छेका लागि ♥ सहित बनाइएको",
  "visa.title": "भिसा गाइड",
  "visa.subtitle": "लोकप्रिय गन्तव्यका लागि सरल भिसा जानकारी — कुनै भाषा-पेचिलो वा कानुनी भाषा छैन। बुक गर्नुअघि प्रवेश आवश्यकताहरू जाँच गर्नुहोस्।",
  "visa.disclaimer": "जानकारी सामान्य मार्गदर्शनका लागि मात्र हो। यात्रा गर्नुअघि सधैँ आधिकारिक दूतावास स्रोतहरू जाँच गर्नुहोस्।",
