  "hotels.title": "होरायज़न स्टेज",
  "hotels.desc": "बुटीक गेस्टहाउसदेखि प्रिमियम रिसोर्टसम्म। हामी शीर्ष नेटवर्कहरू तुलना गर्छौं ताकि तपाईं कोठाको लागि बढी नतिरौं।",
  "hotels.tips_title": "होरायज़न स्टेज सुझावहरू",
  "hotels.tip_1": "दुवै साझेदारमा एउटै होटल खोज्नुस् — एउटै कोठाको लागि पनि मूल्य १०–२०% फरक हुन सक्छ।",
  "hotels.tip_2": "पुष्टि गर्नुअघि सधैं रद्दीकरण नीति जाँच गर्नुस्। निःशुल्क रद्दीकरण केही अतिरिक्त डलरको मूल्य राख्छ।",
  "hotels.tip_3": "Agoda ले एशियाली सम्पत्तिहरूको लागि प्राय: कम शुद्ध मूल्यहरू देखाउँछ; Hotels.com बारम्बार यात्रुहरूलाई पुरस्कृत गर्छ।",
  "hotels.tip_4": "स्थानीय मुद्रामा बुकिङ गर्नु USD मा बुकिङ गर्नुभन्दा कहिलेकाहीं सस्तो हुन सक्छ।",
  "hotels.agoda_title": "Agoda — एशिया र त्यसभन्दा बाहिरको लागि सर्वोत्तम",
  "hotels.agoda_desc": "एशिया, दक्षिण अमेरिका र विश्वव्यापी हबहरूमा होटलहरूको लागि निरन्तर सबैभन्दा कम मूल्य। तत्काल पुष्टिसहित विश्वव्यापी 2M+ सम्पत्तिहरू।",
  "hotels.agoda_cta": "Agoda मा डिल खोज्नुस्",
  "hotels.hotelscom_desc": "उत्तर अमेरिकी यात्रा र लचिलो रद्दीकरण नीतिहरूको लागि उत्कृष्ट। Rewards कार्यक्रम मार्फत प्रत्येक 10 रातको बुकिङमा एउटा निःशुल्क रात।",
  "hotels.hotelscom_cta": "Hotels.com मा खोज्नुस्",
  "hotels.klook_title": "Klook होटल र बन्डलहरू",
  "hotels.klook_desc": "एशियामा यात्रा वा Stay + Play बन्डल बुकिङको लागि उत्तम। Klook ले प्राय: कोठा र भ्रमण एकसाथ बुक गर्दा विशेष छुट प्रदान गर्छ।",
  "hotels.klook_cta": "Klook मा होटल खोज्नुस्",
  "hotels.check_1": "निःशुल्क रद्दीकरणको समयसीमा जाँच गर्नुस् (केवल 'निःशुल्क रद्दीकरण' मात्र होइन)",
  "hotels.check_2": "हालैका समीक्षाहरू पढ्नुस् — मिति अनुसार क्रमबद्ध गर्नुस्, स्कोर अनुसार होइन",
  "hotels.check_3": "ब्रेकफास्ट र करहरू मूल्यमा समावेश छन् कि जाँच गर्नुस्",
  "hotels.check_4": "यदि तपाईंको उडान चाँडो आउँछ भने अर्ली चेक-इनको बारेमा सोध्नुस्",
  "cars.title": "होरायज़न कार भाडा",
  "cars.desc": "काउन्टर लाइनहरू र लुकेका शुल्कहरू छोड्नुस्। आफ्नो यात्राको लागि उत्तम सवारी साधन खोज्न हाम्रो प्रमाणित साझेदारहरूमध्ये एक चयन गर्नुस्।",
  "cars.how_title": "होरायज़न कार भाडा कसरी काम गर्छ",
  "cars.step_1": "एउटा साझेदारमा क्लिक गर्नुस् — तपाईंलाई सिधै उनीहरूको सुरक्षित बुकिङ पृष्ठमा लगिनेछ।",
  "cars.step_2": "पिकअप स्थान, मिति र कार प्रकारद्वारा खोज्नुस्। हाम्रो तर्फबाट कुनै लुकेका शुल्कहरू छैनन्।",
  "cars.step_3": "साझेदारसँग सिधै बुक गर्नुस्। तपाईंको पुष्टि सिधै तपाईंलाई जान्छ।",
  "cars.step_4": "केही लिङ्कहरू सम्बद्ध लिङ्कहरू हुन् — तपाईंलाई कुनै अतिरिक्त लागत बिना हामीले सानो कमिशन कमाउँछौं।",
  "cars.localrent_title": "Localrent — स्थानीय सम्झौताका लागि उत्तम",
  "cars.localrent_desc": "स्थानीय व्यवसायहरूलाई सहयोग गर्नुहोस् र कम जमानतमा अद्वितीय सवारी खोज्नुहोस्। प्रायः 20–40% सस्तो।",
