  "flights.badge_free": "नि:शुल्क",
  "flights.kiwi_desc": "Horizon Hop™ को लागि उत्तम। एक मात्र खोज इन्जिन जसले स्वचालित रूपमा \"Self-Transfer\" मार्गहरू बनाउँछ — एयरलाइनहरूले तपाईंलाई भेट्टाउन नचाहेका बहु-शहर सम्झौताहरू।",
