  "flights.aviasales_desc": "सयौं विश्वव्यापी र क्षेत्रीय एयरलाइनहरू स्क्यान गरी सबैभन्दा कम भाडा खोज्छ।",
  "flights.aviasales_desc_multi": "प्रमाणित बहु-शहर समर्थन — सबैभन्दा कम संयुक्त भाडा खोज्न तपाईंका सबै खण्डहरूमा सयौं एयरलाइनहरू स्क्यान गर्छ।",
  "flights.google_desc": "आधारभूत मूल्य तुलनाको लागि उत्तम उपकरण। अन्यत्र प्रतिबद्ध हुनुअघि उचित मूल्य पाइरहेको प्रमाणित गर्नुहोस्।",
  "flights.google_cta": "Google मा प्रमाणित गर्नुहोस्",
  "flights.visa_heading": "बुकिङ गर्नुअघि प्रवेश आवश्यकताहरू प्रमाणित गर्नुहोस्",
  "flights.visa_desc": "तपाईंको राहदानी + गन्तव्यको लागि भिसा आवश्यकताहरू सेकेन्डमा जाँच गर्नुहोस्।",
  "flights.hop_title": "\"Horizon Hop\" कसरी बुक गर्ने",
  "flights.hop_intro": "Horizon Hop (Self-Transfer भनेर पनि चिनिन्छ) भनेको एउटा सिधा यात्राको सट्टा दुईवटा छुट्टा टिकट बुक गरेर एयरलाइन मूल्य एल्गोरिदमलाई हराउने तरिका हो। यसरी गर्नुहोस्:",
  "flights.hop1_title": "Hub फेला पार्नुहोस्",
  "flights.hop1_body": "तपाईंको सानो गन्तव्यमा सिधा उड्नुको सट्टा (जस्तै Valadares, ब्राजिल), नजिकको सबैभन्दा सस्तो प्रमुख अन्तर्राष्ट्रिय hub खोज्नुहोस् — जस्तै Rio de Janeiro वा São Paulo। Hub टिकट सामान्यतया ४०–६०% सस्तो हुन्छन्।",
  "flights.hop2_title": "Hopper बुक गर्नुहोस्",
  "flights.hop2_body": "सस्तो hub उडान सुनिश्चित गरेपछि, अन्तिम खण्डको लागि छुट्टै स्थानीय बजेट एयरलाइन वा बस बुक गर्नुहोस्। दुई टिकट बीचमा कम्तीमा ३ घण्टा राख्नुहोस्।",
  "flights.hop3_title": "Kiwi प्रयोग गर्नुहोस्",
  "flights.hop3_body": "Kiwi.com एक मात्र खोज इन्जिन हो जसले तपाईंको लागि यी विच्छेदित \"Horizon Hops\" स्वचालित रूपमा जोड्छ। माथिको Kiwi लिंकमा क्लिक गर्नुहोस् र हरियो \"Self-transfer\" ब्याज खोज्नुहोस्।",
  "flights.hop_tip_label": "Horizon सुझाव",
  "flights.hop_tip_body": "Self-Transfer को जोखिम भनेको छुटेको कनेक्सन हो — दोस्रो उडान समात्ने तपाईंको जिम्मेवारी हो। सधैं टिकटहरू बीचमा ३+ घण्टा छोड्नुहोस् र यात्रा बीमा सुनिश्चित गर्नुहोस्।",
  "flights.shield_label": "Horizon शिल्ड",
  "flights.insurance_label": "यात्रा बीमा",
  "flights.insurance_tip": "Self-Transfer यात्राहरूलाई यात्रा बीमा चाहिन्छ। यदि तपाईंले दोस्रो उडान गुमाउनुभयो भने, बीमा मात्र बचाउँछ।",
  "flights.insurance_cta": "EKTA बाट सुरक्षित हुनुहोस् →",
  "flights.connectivity_label": "कनेक्टिभिटी",
  "flights.airalo_desc": "$5 देखि 200+ देशहरूमा डाटा। SIM कार्ड नफेरी, रोमिङ बिल नपरी।",
  "flights.airalo_cta": "Airalo eSIM पाउनुहोस् →",
  "flights.affiliate_note": "साझेदार लिंकहरू सहबद्ध लिंकहरू हुन्। Himal to Horizon ले सानो कमिसन कमाउँछ — यसले तपाईंले तिर्ने मूल्यलाई कहिल्यै असर गर्दैन।",
  "common.verified_partners": "Horizon को बुकिङ सिफारिसहरू",
