  "visa.difficulty_page_title": "सजिलो → गाह्रो: पर्यटक भिसाको कठिनाइ",
  "visa.difficulty_page_subtitle": "हामीले समेटेका सबै गन्तव्यहरू, आवेदन दिन सबैभन्दा सजिलोदेखि सबैभन्दा गाह्रोसम्म क्रमबद्ध।",
  "visa.difficulty_disclaimer": "यो आवश्यकताको जटिलताको क्रम हो, स्वीकृति दरको तथ्यांक होइन। कुनै पनि आप्रवासन निकायले राष्ट्रियताअनुसार भिसा स्वीकृति दर सार्वजनिक गर्दैन, त्यसैले हामी त्यस्तो दाबी गर्दैनौं। बरु, यो स्कोर हामीले प्रत्येक देशको लागि पहिले नै अनुसन्धान गरेको कुराबाट गणना गरिएको हो: तपाईंले कसरी आवेदन दिनुहुन्छ, कति कागजात चाहिन्छ, प्रहरी प्रतिवेदन वा अन्तर्वार्ता साँच्चै आवश्यक छ कि छैन, र प्रशोधनमा सामान्यतया कति समय लाग्छ। \"गाह्रो\" क्रमको मतलब बढी कागजी कार्य र समय हो — स्वीकृतिको कम सम्भावना होइन।",
  "visa.difficulty_loading": "क्रम लोड हुँदै…",
  "visa.difficulty_error": "कठिनाइ क्रम लोड गर्न सकिएन। कृपया फेरि प्रयास गर्नुहोस्।",
  "visa.free_page_title": "भिसा-रहित र आगमनमा भिसा हुने देशहरू",
  "visa.free_page_subtitle": "सबै गन्तव्य जहाँ नेपाली राहदानीलाई प्रवेशका लागि पूर्व-स्वीकृत भिसा चाहिँदैन।",
  "visa.free_disclaimer": "खुला-स्रोत passport-index-dataset परियोजनाबाट संकलित। भिसा नीतिहरू प्रायः परिवर्तन हुन्छन् र सही राष्ट्रियता नियमअनुसार फरक हुन सक्छन्, त्यसैले उडान बुक गर्नुअघि गन्तव्यको आधिकारिक आप्रवासन साइटमा हालको नीति पुष्टि गर्नुहोस्। उडान अघि नै अनलाइन आवेदन दिनुपर्ने देश खोज्दै हुनुहुन्छ? त्यो यसको छेउमा रहेको eVisa ट्याब हो।",
  "visa.up_to": "अधिकतम",
  "visa.stay_varies": "बसाइको अवधि फरक हुन्छ",
  "visa.evisa_page_title": "इभिसा / अनलाइन भिसा हुने देशहरू",
  "visa.evisa_page_subtitle": "उड्नुअघि नै अनलाइन आवेदन दिनुहोस् — दूतावास जानु पर्दैन, अग्रिम भिसा स्टिकर चाहिँदैन।",
  "visa.evisa_disclaimer": "इभिसा आगमनमा हुने भिसा जस्तो होइन — यो यात्रा अघि नै अनलाइन आवेदन दिई स्वीकृत गराउनुपर्छ, सामान्यतया केही दिन अगाडि। खुला-स्रोत passport-index-dataset परियोजनाबाट संकलित; देखाइएको शुल्क र प्रशोधन समय सामान्य सन्दर्भ मात्र हुन्, त्यसैले उडान बुक गर्नुअघि गन्तव्यको आधिकारिक eVisa पोर्टलमा पुष्टि गर्नुहोस्। कुनै पनि आवेदन नै नचाहिने देश खोज्दै हुनुहुन्छ? त्यो यसको छेउमा रहेको भिसा-रहित र आगमनमा भिसा ट्याब हो।",
