  "home.cat_trek": "تقرير الرحلة",
  "home.cat_destination": "دليل الوجهة",
  "home.cat_tips": "نصائح السفر",
  "home.cat_story": "قصة سفر",
  "footer.affiliate_notice": "Himal to Horizon شريك تابع لـ Travelpayouts. قد نحصل على عمولة من الحجوزات التي تتم عبر روابطنا.",
  "about.back": "الرئيسية",
  "about.hero_subtitle": "مشروع وُلد من إحباط بسيط — لا ينبغي أن يكون حجز تذاكر الطيران أشبه بوظيفة ثانية.",
  "about.creator_title": "مرحباً، أنا Jiwan",
  "about.creator_p1": "بنيت Himal to Horizon لأنني أؤمن بأن السفر الرائع لا ينبغي أن يكون حكراً على من لديهم وقت غير محدود أو وكيل سفر في متناول اليد. ينبغي للناس العاديين أن يتمكنوا من السفر مثل المحترفين.",
  "about.creator_p2": "بدأت الفكرة ببساطة: كنت أقضي ساعات عبر علامات تبويب متعددة في محاولة لإيجاد أفضل وقت للسفر، لأدرك أنني كنت أنظر إلى المشكلة بالطريقة الخاطئة. بدلاً من البحث عن تاريخ وأمل أن يكون السعر جيداً، ماذا لو أخبرتك الأداة بأفضل فترة — بناءً على المدة التي تريد فعلاً البقاء فيها؟",
  "about.creator_p3": "هذا ما أصبح Stay Optimizer™، وفي نهاية المطاف، Himal to Horizon.",
  "about.youtube_title": "قناة يوتيوب",
  "about.youtube_desc": "قناة Himal to Horizon على يوتيوب هي المكان الذي أشارك فيه تجارب سفر حقيقية — خام، وغير مفلترة، وصادقة. لا أجنحة فاخرة ولا كمال مصطنع. فقط قصص حقيقية من الطريق تساعدك على التخطيط بذكاء والسفر بمزيد من الثقة.",
  "about.youtube_link": "شاهد على يوتيوب",
  "about.photo_title": "التصوير الفوتوغرافي",
  "about.photo_desc": "كل وجهة تحكي قصة من خلال الضوء. أنا شغوف بالتصوير الفوتوغرافي للمناظر الطبيعية والسفر — من فجر الهيمالايا فوق الحواف إلى مشاهد الشوارع الهادئة في مدن يطير فوقها معظم السياح. التصوير هو طريقتي في التباطؤ ورؤية المكان حقاً.",
  "about.mission_title": "المهمة",
  "about.mission_p1": "تم بناء Himal to Horizon لما أسميه الناس العاديين — أشخاص يعملون بجد، ويوفرون بتفكير، ويستحقون رؤية العالم دون أن يُستغلوا بأسعار مرتفعة أو يتجمدوا بسبب التردد.",
  "about.pillar_1_label": "ابحث عن أفضل نافذة",
  "about.pillar_1_desc": "ليس فقط أرخص تاريخ — أفضل مزيج من السعر والمدة والمرونة.",
  "about.pillar_2_label": "سافر أكثر في العالم",
  "about.pillar_2_desc": "إقامات أطول بأسعار أفضل تعني دولاً أكثر، تجارب أكثر، قصصاً أكثر.",
  "about.pillar_3_label": "لا تحتاج معرفة خاصة",
  "about.pillar_3_desc": "الأدوات والرؤى المبنية هنا هي ما يعرفه المسافرون المتكررون بالفعل. الآن الجميع يمتلكها.",
  "about.cta": "ابدأ الاستكشاف",
  "about.cta_footer": "لا حاجة لحساب · أسعار مباشرة من Travelpayouts · مصنوع بـ ♥ للناس العاديين",
