  "hotels.title": "هورايزن للإقامة",
  "hotels.desc": "من دور الضيافة الراقية إلى المنتجعات الفاخرة. نقارن أفضل الشبكات حتى لا تدفع أكثر من اللازم لغرفتك.",
  "hotels.tips_title": "نصائح هورايزن للإقامة",
  "hotels.tip_1": "ابحث عن نفس الفندق لدى الشركاء — قد تختلف الأسعار بنسبة ١٠-٢٠٪ لنفس الغرفة.",
  "hotels.tip_2": "تحقق دائماً من سياسة الإلغاء قبل التأكيد. الإلغاء المجاني يستحق بضعة دولارات إضافية.",
  "hotels.tip_3": "Agoda تعرض أسعاراً أقل للعقارات الآسيوية؛ Hotels.com يكافئ المسافرين المتكررين.",
  "hotels.tip_4": "الحجز بالعملة المحلية قد يكون أحياناً أرخص من الحجز بالدولار.",
  "hotels.agoda_title": "Agoda — الأفضل لآسيا وما بعدها",
  "hotels.agoda_desc": "أدنى الأسعار باستمرار للفنادق في آسيا وأمريكا الجنوبية والمراكز العالمية. أكثر من 2 مليون عقار حول العالم مع تأكيد فوري.",
  "hotels.agoda_cta": "ابحث عن صفقات في Agoda",
  "hotels.hotelscom_desc": "رائع للسفر في أمريكا الشمالية وسياسات الإلغاء المرنة. اكسب ليلة مجانية لكل 10 ليالٍ محجوزة.",
  "hotels.hotelscom_cta": "البحث في Hotels.com",
