  "hotels.klook_desc": "مثالي للسفر في آسيا أو حجز باقات الإقامة + الترفيه. غالباً ما يقدم Klook خصومات حصرية عند حجز غرفتك والجولات معاً.",
  "hotels.klook_cta": "ابحث عن فنادق في Klook",
