  "footer.affiliate_notice": "Himal to Horizon, Travelpayouts का सहबद्ध भागीदार है। हमारे लिंक के माध्यम से की गई बुकिंग पर हमें कमीशन मिल सकता है।",
  "about.back": "होम",
  "about.hero_subtitle": "एक साधारण निराशा से जन्मा प्रोजेक्ट — फ्लाइट बुक करना दूसरी नौकरी जैसा नहीं लगना चाहिए।",
  "about.creator_title": "नमस्ते, मैं Jiwan हूँ",
  "about.creator_p1": "मैंने Himal to Horizon बनाया क्योंकि मेरा मानना है कि अद्भुत यात्रा असीमित समय या ट्रैवल एजेंट वाले लोगों के लिए आरक्षित नहीं होनी चाहिए। सामान्य लोगों को भी पेशेवरों की तरह यात्रा करने में सक्षम होना चाहिए।",
  "about.creator_p2": "विचार सरलता से शुरू हुआ: मैं घंटों कई टैब पर कहीं उड़ने का सबसे अच्छा समय खोजता रहा, और फिर एहसास हुआ कि मैं समस्या को गलत तरीके से देख रहा था। तारीख खोजने और कीमत अच्छी होने की उम्मीद करने की बजाय, क्या होगा अगर टूल ही आपको सबसे अच्छी विंडो बता दे — आप वास्तव में कितने दिन रहना चाहते हैं उसके आधार पर?",
  "about.creator_p3": "यही Stay Optimizer™ बना और अंततः Himal to Horizon।",
  "about.youtube_title": "YouTube चैनल",
  "about.youtube_desc": "Himal to Horizon YouTube चैनल वह जगह है जहाँ मैं असली यात्रा अनुभव साझा करता हूँ — कच्चे, अनफ़िल्टर्ड और ईमानदार। कोई लग्ज़री सुइट या क्यूरेटेड परफेक्शन नहीं। बस रास्ते से असली कहानियाँ जो आपको स्मार्ट तरीके से योजना बनाने और आत्मविश्वास के साथ यात्रा करने में मदद करती हैं।",
  "about.youtube_link": "YouTube पर देखें",
  "about.photo_title": "फोटोग्राफी",
  "about.photo_desc": "हर गंतव्य प्रकाश के माध्यम से एक कहानी बताता है। मुझे लैंडस्केप और ट्रैवल फोटोग्राफी का जुनून है — हिमालयी भोर की किरणों से लेकर उन शहरों की शांत गली के दृश्यों तक जिन्हें ज़्यादातर पर्यटक उड़ान में देखते हैं। फोटोग्राफी वह तरीका है जिससे मैं धीमा होता हूँ और किसी जगह को सच में देखता हूँ।",
  "about.mission_title": "मिशन",
  "about.mission_p1": "Himal to Horizon उन लोगों के लिए बना है जिन्हें मैं 'आम जन' कहता हूँ — वे लोग जो कड़ी मेहनत करते हैं, सोच-समझकर बचत करते हैं, और बढ़ी हुई कीमतों से ठगे बिना या अनिर्णय में उलझे बिना दुनिया देखने के हकदार हैं।",
  "about.pillar_1_label": "सबसे अच्छी विंडो खोजें",
  "about.pillar_1_desc": "सिर्फ सबसे सस्ती तारीख नहीं — कीमत, अवधि और लचीलेपन का सबसे अच्छा संयोजन।",
  "about.pillar_2_label": "दुनिया और ज़्यादा घूमें",
  "about.pillar_2_desc": "बेहतर कीमतों पर लंबे प्रवास का मतलब है ज़्यादा देश, ज़्यादा अनुभव, ज़्यादा कहानियाँ।",
  "about.pillar_3_label": "कोई विशेष ज्ञान आवश्यक नहीं",
  "about.pillar_3_desc": "यहाँ बने टूल और जानकारी वे हैं जो बार-बार उड़ने वाले पहले से जानते हैं। अब सबके पास हैं।",
  "about.cta": "अन्वेषण शुरू करें",
  "about.cta_footer": "खाता ज़रूरी नहीं · Travelpayouts से लाइव किराए · आम जन के लिए ♥ के साथ बनाया",
  "visa.title": "वीज़ा गाइड",
  "visa.subtitle": "लोकप्रिय गंतव्यों के लिए सरल वीज़ा जानकारी — कोई जटिल भाषा नहीं। बुक करने से पहले प्रवेश आवश्यकताएँ जाँचें।",
  "visa.disclaimer": "जानकारी केवल सामान्य मार्गदर्शन के लिए है। यात्रा से पहले हमेशा आधिकारिक दूतावास स्रोतों की जाँच करें।",
