  "hotels.title": "होरायज़न स्टेज़",
  "hotels.desc": "बुटीक गेस्टहाउस से प्रीमियम रिसॉर्ट तक। हम शीर्ष नेटवर्क की तुलना करते हैं ताकि आप कमरे के लिए अधिक भुगतान न करें।",
  "hotels.tips_title": "होरायज़न स्टेज़ सुझाव",
  "hotels.tip_1": "दोनों भागीदारों पर एक ही होटल खोजें — एक ही कमरे के लिए कीमतें 10–20% अलग हो सकती हैं।",
  "hotels.tip_2": "पुष्टि करने से पहले रद्दीकरण नीति हमेशा जांचें। निःशुल्क रद्दीकरण कुछ अतिरिक्त डॉलर के लायक है।",
  "hotels.tip_3": "Agoda अक्सर एशियाई संपत्तियों के लिए कम शुद्ध मूल्य दिखाता है; Hotels.com बार-बार बुकर्स को पुरस्कृत करता है।",
  "hotels.tip_4": "स्थानीय मुद्रा में बुकिंग कभी-कभी USD में बुकिंग से सस्ती हो सकती है।",
  "hotels.agoda_title": "Agoda — एशिया और उससे परे के लिए सर्वश्रेष्ठ",
  "hotels.agoda_desc": "एशिया, दक्षिण अमेरिका और वैश्विक केंद्रों में होटलों के लिए लगातार सबसे कम कीमतें। तत्काल पुष्टि के साथ दुनिया भर में 2M+ संपत्तियां।",
  "hotels.agoda_cta": "Agoda पर डील खोजें",
  "hotels.hotelscom_desc": "उत्तरी अमेरिकी यात्रा और लचीली रद्दीकरण नीतियों के लिए बढ़िया। Rewards प्रोग्राम के माध्यम से हर 10 रातों की बुकिंग पर एक मुफ्त रात कमाएं।",
  "hotels.hotelscom_cta": "Hotels.com पर खोजें",
  "hotels.klook_title": "Klook होटल और बंडल",
  "hotels.klook_desc": "एशिया में यात्रा या Stay + Play बंडल बुक करने के लिए परफेक्ट। जब आप कमरा और टूर एक साथ बुक करते हैं तो Klook अक्सर एक्सक्लूसिव छूट देता है।",
  "hotels.klook_cta": "Klook पर होटल खोजें",
  "hotels.check_1": "मुफ्त रद्दीकरण की समय सीमा जांचें (केवल 'मुफ्त रद्दीकरण' नहीं)",
  "hotels.check_2": "हाल की समीक्षाएं पढ़ें — तारीख के अनुसार क्रमबद्ध करें, स्कोर के अनुसार नहीं",
  "hotels.check_3": "पुष्टि करें कि नाश्ता और कर कीमत में शामिल हैं",
  "hotels.check_4": "अगर आपकी फ्लाइट जल्दी आती है तो अर्ली चेक-इन के बारे में पूछें",
  "cars.title": "होरायज़न कार रेंटल",
  "cars.desc": "काउंटर लाइनों और छुपे शुल्कों को छोड़ें। अपनी यात्रा के लिए सर्वोत्तम वाहन खोजने के लिए हमारे सत्यापित भागीदारों में से एक चुनें।",
  "cars.how_title": "होरायज़न कार रेंटल कैसे काम करता है",
  "cars.step_1": "किसी भागीदार पर क्लिक करें — आपको सीधे उनके सुरक्षित बुकिंग पृष्ठ पर ले जाया जाएगा।",
  "cars.step_2": "पिकअप स्थान, तारीखें और कार प्रकार से खोजें। हमारी ओर से कोई छुपे शुल्क नहीं।",
  "cars.step_3": "सीधे भागीदार के साथ बुक करें। आपकी पुष्टि सीधे आपके पास जाती है।",
  "cars.step_4": "कुछ लिंक सहयोगी लिंक हैं — हम आपको बिना किसी अतिरिक्त लागत के एक छोटा कमीशन कमाते हैं।",
  "cars.localrent_title": "Localrent — स्थानीय सौदों के लिए सर्वश्रेष्ठ",
  "cars.localrent_desc": "स्थानीय व्यवसायों का समर्थन करें और कम जमा राशि के साथ अनूठे वाहन खोजें। अक्सर 20–40% सस्ता।",
