  "cars.klook_title": "Klook कार रेंटल",
  "cars.klook_desc": "वैश्विक हवाई अड्डों और बड़े ब्रांडों के लिए आदर्श। बिना छिपे शुल्क के शीर्ष फ्लीट की तुलना करें।",
