  "flights.badge_self_transfer": "सेल्फ-ट्रांसफर",
  "flights.badge_horizons_pick": "Horizon की पसंद",
  "flights.badge_free": "मुफ़्त",
  "flights.kiwi_desc": "Horizon Hop™ के लिए सबसे अच्छा। एकमात्र सर्च इंजन जो स्वचालित रूप से \"Self-Transfer\" मार्ग बनाता है — बहु-शहर सौदे जो एयरलाइंस नहीं चाहतीं कि आप पाएं।",
  "flights.kiwi_cta": "Kiwi पर खोजें",
  "flights.aviasales_heading": "Aviasales (वैश्विक मेटासर्च)",
  "flights.aviasales_desc": "सबसे कम किराए खोजने के लिए सैकड़ों वैश्विक और क्षेत्रीय एयरलाइनों को स्कैन करता है।",
  "flights.aviasales_desc_multi": "सत्यापित बहु-शहर समर्थन — सबसे कम संयुक्त किराया खोजने के लिए आपके सभी खंडों में सैकड़ों एयरलाइनों को स्कैन करता है।",
  "flights.google_desc": "आधार मूल्य तुलना के लिए सबसे अच्छा उपकरण। कहीं और प्रतिबद्ध होने से पहले उचित मूल्य सत्यापित करें।",
  "flights.google_cta": "Google पर सत्यापित करें",
  "flights.visa_heading": "बुकिंग से पहले प्रवेश आवश्यकताएं सत्यापित करें",
  "flights.visa_desc": "अपने पासपोर्ट + गंतव्य के लिए वीज़ा आवश्यकताएं सेकंडों में जांचें।",
  "flights.hop_title": "\"Horizon Hop\" कैसे बुक करें",
  "flights.hop_intro": "Horizon Hop (Self-Transfer के रूप में भी जाना जाता है) एक सीधे यात्रा कार्यक्रम के बजाय दो अलग टिकट बुक करके एयरलाइन मूल्य निर्धारण एल्गोरिदम को हराने का तरीका है। ऐसे करें:",
  "flights.hop1_title": "Hub खोजें",
  "flights.hop1_body": "अपने छोटे गंतव्य पर सीधे उड़ने के बजाय, पास का सबसे सस्ता प्रमुख अंतरराष्ट्रीय hub खोजें। Hub टिकट आमतौर पर 40-60% सस्ते होते हैं।",
  "flights.hop2_title": "Hopper बुक करें",
  "flights.hop2_body": "सस्ती hub उड़ान सुरक्षित करने के बाद, अंतिम खंड के लिए अलग स्थानीय बजट एयरलाइन या बस बुक करें। दो टिकटों के बीच कम से कम 3 घंटे रखें।",
  "flights.hop3_title": "Kiwi उपयोग करें",
  "flights.hop3_body": "Kiwi.com एकमात्र सर्च इंजन है जो आपके लिए इन डिस्कनेक्ट किए गए \"Horizon Hops\" को स्वचालित रूप से जोड़ता है। ऊपर Kiwi लिंक पर क्लिक करें और हरे \"Self-transfer\" बैज की तलाश करें।",
  "flights.hop_tip_label": "Horizon सुझाव",
  "flights.hop_tip_body": "Self-Transfer का जोखिम छूटा हुआ कनेक्शन है — दूसरी उड़ान पकड़ना आपकी जिम्मेदारी है। हमेशा टिकटों के बीच 3+ घंटे रखें और यात्रा बीमा सुनिश्चित करें।",
  "flights.shield_label": "Horizon शील्ड",
  "flights.insurance_label": "यात्रा बीमा",
  "flights.insurance_tip": "Self-Transfer यात्राओं के लिए यात्रा बीमा आवश्यक है। यदि आप दूसरी उड़ान चूक जाते हैं, तो बीमा ही एकमात्र बचाव है।",
  "flights.insurance_cta": "EKTA से सुरक्षित हों →",
  "flights.connectivity_label": "कनेक्टिविटी",
  "flights.airalo_desc": "$5 से 200+ देशों में डाटा। SIM बदले बिना, रोमिंग बिल के बिना।",
  "flights.airalo_cta": "Airalo eSIM पाएं →",
  "flights.affiliate_note": "साझेदार लिंक सहबद्ध लिंक हैं। Himal to Horizon एक छोटा कमीशन कमाता है — यह कभी भी आपके द्वारा भुगतान की जाने वाली कीमत को प्रभावित नहीं करता।",
