  "footer.affiliate_notice": "Himal to Horizon হল Travelpayouts-এর অ্যাফিলিয়েট পার্টনার। আমাদের লিঙ্কের মাধ্যমে বুকিংয়ে আমরা কমিশন পেতে পারি।",
  "about.back": "হোম",
  "about.hero_subtitle": "একটি সহজ হতাশা থেকে জন্ম নেওয়া প্রকল্প — ফ্লাইট বুক করা দ্বিতীয় চাকরির মতো মনে হওয়া উচিত নয়।",
  "about.creator_title": "হ্যালো, আমি Jiwan",
  "about.creator_p1": "আমি Himal to Horizon তৈরি করেছি কারণ আমি বিশ্বাস করি যে অসাধারণ ভ্রমণ অসীম সময় বা ট্র্যাভেল এজেন্ট থাকা মানুষদের জন্য সংরক্ষিত হওয়া উচিত নয়। সাধারণ মানুষও পেশাদারদের মতো ভ্রমণ করতে পারা উচিত।",
  "about.creator_p2": "ধারণাটি সহজভাবে শুরু হয়েছিল: আমি ঘণ্টার পর ঘণ্টা একাধিক ট্যাবে কোথাও উড়ে যাওয়ার সেরা সময় খুঁজছিলাম, শুধুমাত্র বুঝতে পারলাম যে আমি সমস্যাটি ভুলভাবে দেখছিলাম। একটি তারিখ খোঁজার এবং দাম ভালো হওয়ার আশা করার পরিবর্তে, টুলটি যদি আপনাকেই সেরা উইন্ডো বলে দিত — আপনি আসলে কতদিন থাকতে চান তার ভিত্তিতে?",
  "about.creator_p3": "সেটিই Stay Optimizer™ হয়ে উঠেছে, এবং অবশেষে, Himal to Horizon।",
  "about.youtube_title": "YouTube চ্যানেল",
  "about.youtube_desc": "Himal to Horizon YouTube চ্যানেল হল সেই জায়গা যেখানে আমি বাস্তব ভ্রমণ অভিজ্ঞতা শেয়ার করি — কাঁচা, আনফিল্টার্ড এবং সৎ। কোনো বিলাসবহুল সুইট বা কিউরেটেড পারফেকশন নেই। শুধু রাস্তা থেকে সত্যিকারের গল্প যা আপনাকে স্মার্টভাবে পরিকল্পনা করতে এবং আরও আত্মবিশ্বাসের সাথে ভ্রমণ করতে সাহায্য করে।",
  "about.youtube_link": "YouTube-এ দেখুন",
  "about.photo_title": "ফটোগ্রাফি",
  "about.photo_desc": "প্রতিটি গন্তব্য আলোর মাধ্যমে একটি গল্প বলে। আমি ল্যান্ডস্কেপ এবং ট্র্যাভেল ফটোগ্রাফিতে আবেগপ্রবণ — হিমালয়ের ভোরের আলো থেকে শুরু করে শহরের শান্ত রাস্তার দৃশ্যে যা বেশিরভাগ পর্যটকরা উপরে উড়ে যায়। ফটোগ্রাফি হলো আমার ধীর হওয়া এবং সত্যিকারভাবে একটি জায়গা দেখার পদ্ধতি।",
  "about.mission_title": "মিশন",
  "about.mission_p1": "Himal to Horizon তৈরি হয়েছে তাদের জন্য যাদের আমি 'সাধারণ মানুষ' বলি — যারা কঠোর পরিশ্রম করে, সুচিন্তিতভাবে সঞ্চয় করে, এবং বাড়তি ভাড়ায় প্রতারিত হওয়া বা অনির্ণয়ে স্থবির হওয়া ছাড়াই বিশ্ব দেখার যোগ্য।",
  "about.pillar_1_label": "সেরা উইন্ডো খুঁজুন",
  "about.pillar_1_desc": "শুধু সবচেয়ে সস্তা তারিখ নয় — মূল্য, সময়কাল এবং নমনীয়তার সেরা সমন্বয়।",
  "about.pillar_2_label": "বিশ্বে বেশি ভ্রমণ করুন",
  "about.pillar_2_desc": "ভালো দামে দীর্ঘ থাকার মানে বেশি দেশ, বেশি অভিজ্ঞতা, বেশি গল্প।",
  "about.pillar_3_label": "কোনো বিশেষ জ্ঞান প্রয়োজন নেই",
  "about.pillar_3_desc": "এখানে তৈরি সরঞ্জাম এবং অন্তর্দৃষ্টি সেগুলো যা ঘন ঘন ফ্লায়াররা ইতিমধ্যে জানে। এখন সবার কাছে আছে।",
  "about.cta": "অন্বেষণ শুরু করুন",
  "about.cta_footer": "কোনো অ্যাকাউন্ট প্রয়োজন নেই · Travelpayouts লাইভ ভাড়া · সাধারণ মানুষের জন্য ♥ দিয়ে তৈরি",
  "visa.title": "ভিসা গাইড",
  "visa.subtitle": "জনপ্রিয় গন্তব্যের জন্য সহজ ভিসা তথ্য — কোনো জটিল ভাষা নেই। বুক করার আগে প্রবেশের প্রয়োজনীয়তা যাচাই করুন।",
  "visa.disclaimer": "তথ্য শুধুমাত্র সাধারণ নির্দেশিকার জন্য। ভ্রমণের আগে সর্বদা আনুষ্ঠানিক দূতাবাস সূত্র যাচাই করুন।",
