  "hotels.title": "হরাইজন স্টেজ",
  "hotels.desc": "বুটিক গেস্টহাউস থেকে প্রিমিয়াম রিসোর্ট পর্যন্ত। আমরা শীর্ষ নেটওয়ার্কগুলি তুলনা করি যাতে আপনি ঘরের জন্য অতিরিক্ত না দেন।",
  "hotels.tips_title": "হরাইজন স্টেজ পরামর্শ",
  "hotels.tip_1": "উভয় অংশীদারে একই হোটেল খুঁজুন — একই ঘরের জন্যও দাম ১০-২০% আলাদা হতে পারে।",
  "hotels.tip_2": "নিশ্চিত করার আগে সর্বদা বাতিল নীতি পরীক্ষা করুন। বিনামূল্যে বাতিলকরণ মূল্যবান।",
  "hotels.tip_3": "Agoda প্রায়শই এশিয়ান সম্পত্তির জন্য কম নেট মূল্য দেখায়; Hotels.com ঘন ঘন বুকারদের পুরস্কৃত করে।",
  "hotels.tip_4": "স্থানীয় মুদ্রায় বুকিং করা USD-এ বুকিং করার চেয়ে কম ব্যয়বহুল হতে পারে।",
  "hotels.agoda_title": "Agoda — এশিয়া ও তার বাইরের জন্য সেরা",
  "hotels.agoda_desc": "এশিয়া, দক্ষিণ আমেরিকা এবং বৈশ্বিক হাবগুলিতে হোটেলের জন্য ধারাবাহিকভাবে সর্বনিম্ন দাম। তাৎক্ষণিক নিশ্চিতকরণ সহ বিশ্বজুড়ে 2M+ সম্পত্তি।",
  "hotels.agoda_cta": "Agoda-তে ডিল খুঁজুন",
  "hotels.hotelscom_desc": "উত্তর আমেরিকার ভ্রমণ এবং নমনীয় বাতিল নীতির জন্য দুর্দান্ত। রিওয়ার্ড প্রোগ্রামের মাধ্যমে প্রতি ১০ রাতে বিনামূল্যে একটি রাত পান।",
