  "cars.title": "হরাইজন কার রেন্টাল",
  "cars.desc": "কাউন্টার লাইন এবং লুকানো ফি এড়িয়ে চলুন। আপনার ভ্রমণের জন্য সেরা যানবাহন খুঁজে পেতে আমাদের যাচাইকৃত অংশীদারদের একটি বেছে নিন।",
  "cars.how_title": "হরাইজন কার রেন্টাল কীভাবে কাজ করে",
