  "cars.step_2": "পিকআপ স্থান, তারিখ এবং গাড়ির ধরন দিয়ে অনুসন্ধান করুন। আমাদের পক্ষ থেকে কোনো লুকানো ফি নেই।",
  "cars.step_3": "সরাসরি অংশীদারের সাথে বুক করুন। আপনার নিশ্চিতকরণ সরাসরি আপনার কাছে যায়।",
  "cars.step_4": "কিছু লিঙ্ক অ্যাফিলিয়েট লিঙ্ক — আমরা আপনার কোনো অতিরিক্ত খরচ ছাড়াই কমিশন উপার্জন করি।",
