  "flights.hop_title": "\"Horizon Hop\" কীভাবে বুক করবেন",
  "flights.hop_intro": "Horizon Hop (Self-Transfer নামেও পরিচিত) হলো একটি সরাসরি ভ্রমণের পরিবর্তে দুটি আলাদা টিকিট বুক করে এয়ারলাইন মূল্য নির্ধারণ অ্যালগরিদমকে হারানোর উপায়।",
  "flights.hop1_title": "হাব খুঁজুন",
  "flights.hop1_body": "আপনার ছোট গন্তব্যে সরাসরি না উড়ে, কাছের সবচেয়ে সস্তা প্রধান আন্তর্জাতিক হাব খুঁজুন। হাব টিকিট সাধারণত ৪০-৬০% সস্তা।",
  "flights.hop2_title": "হপার বুক করুন",
  "flights.hop2_body": "সস্তা হাব ফ্লাইট নিশ্চিত করার পর, শেষ লেগের জন্য আলাদা স্থানীয় বাজেট এয়ারলাইন বা বাস বুক করুন। দুটি টিকিটের মধ্যে কমপক্ষে ৩ ঘণ্টা রাখুন।",
  "flights.hop3_title": "Kiwi ব্যবহার করুন",
  "flights.hop3_body": "Kiwi.com একমাত্র সার্চ ইঞ্জিন যা আপনার জন্য এই বিচ্ছিন্ন \"Horizon Hops\" স্বয়ংক্রিয়ভাবে জোড়া দেয়।",
  "flights.hop_tip_label": "Horizon টিপ",
  "flights.hop_tip_body": "Self-Transfer-এর ঝুঁকি হলো মিসড কানেকশন। সর্বদা টিকিটের মধ্যে ৩+ ঘণ্টা রাখুন এবং ভ্রমণ বীমা নিশ্চিত করুন।",
