  "visa.difficulty_page_subtitle": "আমাদের কভার করা প্রতিটি গন্তব্য, আবেদন করা সবচেয়ে সহজ থেকে সবচেয়ে কঠিন পর্যন্ত সাজানো।",
  "visa.difficulty_disclaimer": "এটি প্রয়োজনীয়তার জটিলতার র‍্যাঙ্কিং, অনুমোদনের হারের পরিসংখ্যান নয়। কোনো অভিবাসন কর্তৃপক্ষ জাতীয়তা অনুযায়ী ভিসা গ্রহণের হার প্রকাশ করে না, তাই আমরা তেমন দাবি করি না। বরং, এই স্কোরটি আমরা প্রতিটি দেশের জন্য ইতিমধ্যে যা গবেষণা করেছি তা থেকে গণনা করা হয়েছে: আপনি কীভাবে আবেদন করেন, কতগুলো নথি প্রয়োজন, পুলিশ ক্লিয়ারেন্স সার্টিফিকেট বা সাক্ষাৎকার সত্যিই প্রয়োজন কিনা, এবং প্রক্রিয়াকরণে সাধারণত কত সময় লাগে। একটি \"কঠিন\" র‍্যাঙ্কিং মানে বেশি কাগজপত্র ও সময় — অনুমোদনের কম সম্ভাবনা নয়।",
  "visa.difficulty_loading": "র‍্যাঙ্কিং লোড হচ্ছে…",
  "visa.difficulty_error": "কঠিনতার র‍্যাঙ্কিং লোড করা যায়নি। অনুগ্রহ করে আবার চেষ্টা করুন।",
  "visa.free_page_title": "ভিসামুক্ত ও অন-অ্যারাইভাল দেশ",
  "visa.free_page_subtitle": "প্রতিটি গন্তব্য যেখানে একটি নেপালি পাসপোর্টের প্রবেশের জন্য পূর্ব-অনুমোদিত ভিসার প্রয়োজন নেই।",
  "visa.free_disclaimer": "ওপেন-সোর্স passport-index-dataset প্রকল্প থেকে সংকলিত। ভিসা নীতি প্রায়ই পরিবর্তিত হয় এবং সঠিক জাতীয়তার নিয়ম অনুযায়ী ভিন্ন হতে পারে, তাই ফ্লাইট বুক করার আগে গন্তব্যের সরকারি অভিবাসন সাইটে বর্তমান নীতি নিশ্চিত করুন। ফ্লাইটের আগে অনলাইনে আবেদন করতে হয় এমন দেশ খুঁজছেন? সেটি পাশের eVisa ট্যাব।",
  "visa.up_to": "সর্বোচ্চ",
  "visa.stay_varies": "থাকার সময়কাল পরিবর্তিত হয়",
  "visa.evisa_page_title": "ই-ভিসা / অনলাইন ভিসা দেশ",
  "visa.evisa_page_subtitle": "উড়ানোর আগে অনলাইনে আবেদন করুন — দূতাবাসে যাওয়ার প্রয়োজন নেই, আগে থেকে ভিসা স্টিকার নেই।",
  "visa.evisa_disclaimer": "ই-ভিসা অন-অ্যারাইভাল ভিসার মতো নয় — ভ্রমণের আগে অনলাইনে আবেদন করে অনুমোদন নিতে হয়, সাধারণত কয়েক দিন আগে। ওপেন-সোর্স passport-index-dataset প্রকল্প থেকে সংকলিত; দেখানো ফি ও প্রক্রিয়াকরণ সময় সাধারণ রেফারেন্স মাত্র, তাই ফ্লাইট বুক করার আগে গন্তব্যের সরকারি ই-ভিসা পোর্টালে নিশ্চিত করুন। কোনো আবেদনই লাগে না এমন দেশ খুঁজছেন? সেটি পাশের ভিসামুক্ত ও অন-অ্যারাইভাল ট্যাব।",
