  "home.cat_story": "여행 이야기",
  "footer.affiliate_notice": "Himal to Horizon은 Travelpayouts의 제휴 파트너입니다. 저희 링크를 통해 예약하면 수수료를 받을 수 있습니다.",
  "about.back": "홈",
  "about.hero_subtitle": "간단한 불만에서 탄생한 프로젝트 — 항공편 예약이 두 번째 직업처럼 느껴져서는 안 됩니다.",
  "about.creator_title": "안녕하세요, 저는 Jiwan입니다",
  "about.creator_p1": "저는 Himal to Horizon YouTube 채널의 여행 크리에이터 Jiwan입니다. 채널은 진짜 여행에 관한 것입니다 — 협찬 호텔이나 완벽하게 연출된 여행이 아닌, 당신과 저 같은 평범한 사람들이 세상을 더 현명하게 탐험하도록 돕는 솔직한 여행기입니다.",
  "about.creator_p2": "이 도구는 개인적인 불만에서 만들었습니다. 최적의 여행 시기를 찾기 위해 여러 탭을 몇 시간이나 뒤지다가 문제를 잘못 바라보고 있었다는 걸 깨달았습니다. 날짜를 검색하고 가격이 좋기를 바라는 대신, 실제로 머물고 싶은 기간에 맞춰 최적 시기를 알려주는 도구가 있다면 어떨까요?",
  "about.creator_p3": "그것이 Stay Optimizer™가 되었고, 결국 Himal to Horizon이 되었습니다 — 열심히 일하고, 신중하게 저축하며, 바가지 요금 없이 세상을 탐험할 자격이 있는 평범한 사람들을 위해 만든 서비스입니다.",
  "about.youtube_title": "YouTube 채널",
  "about.youtube_desc": "Himal to Horizon YouTube 채널은 진짜 여행 경험을 공유하는 곳입니다 — 날것의, 거르지 않은, 솔직한 여행기. 더 현명하게 계획하고 더 자신 있게 여행하도록 돕는 진정한 이야기들.",
  "about.youtube_link": "YouTube에서 보기",
  "about.photo_title": "사진",
  "about.photo_desc": "모든 목적지는 빛을 통해 이야기를 전합니다. 저는 풍경 및 여행 사진에 열정을 가지고 있습니다 — 히말라야 새벽부터 대부분의 관광객이 지나치는 도시의 조용한 거리까지.",
  "about.mission_title": "미션",
  "about.mission_p1": "Himal to Horizon은 제가 '평범한 조'라고 부르는 사람들을 위해 만들었습니다 — 열심히 일하고, 신중하게 저축하며, 터무니없는 요금에 지불하거나 결정에 마비되지 않고 세상을 탐험할 자격이 있는 사람들.",
  "about.pillar_1_label": "최적 시기 찾기",
  "about.pillar_1_desc": "가장 저렴한 날짜만이 아닌 — 가격, 기간, 유연성의 최적 조합.",
  "about.pillar_2_label": "세상을 더 많이 여행하기",
  "about.pillar_2_desc": "더 좋은 가격의 더 긴 체류는 더 많은 나라, 더 많은 경험, 더 많은 이야기를 의미합니다.",
  "about.pillar_3_label": "전문 지식 불필요",
  "about.pillar_3_desc": "여기서 만든 도구와 인사이트는 빈번한 여행자들이 이미 알고 있는 것들입니다. 이제 모두가 사용할 수 있습니다.",
  "about.cta": "탐험 시작",
  "about.cta_footer": "계정 불필요 · Travelpayouts 제공 요금 · 평범한 조를 위해 ♥로 제작",
  "visa.title": "비자 안내",
  "visa.subtitle": "인기 목적지의 간단한 비자 정보 — 전문 용어 없이. 예약 전 입국 요건을 확인하세요.",
