  "visa.documents_label": "서류",
  "visa.difficulty_page_title": "쉬움 → 어려움: 관광 비자 난이도",
  "visa.difficulty_page_subtitle": "저희가 다루는 모든 목적지를 신청이 가장 쉬운 순서부터 가장 어려운 순서로 정렬했습니다.",
  "visa.difficulty_disclaimer": "이는 요건 복잡도 순위이며, 승인율 통계가 아닙니다. 어떤 이민 당국도 국적별 비자 승인율을 공개하지 않으므로 저희도 그런 자료가 있다고 주장하지 않습니다. 대신 이 점수는 각 국가에 대해 이미 조사한 내용을 바탕으로 계산됩니다: 신청 방법, 필요한 서류 수, 범죄경력 확인서나 인터뷰가 실제로 필요한지, 그리고 처리에 보통 얼마나 걸리는지 등입니다. \"어려움\" 등급은 서류와 시간이 더 든다는 의미일 뿐, 승인 가능성이 낮다는 뜻이 아닙니다.",
  "visa.difficulty_loading": "순위 불러오는 중…",
  "visa.difficulty_error": "난이도 순위를 불러올 수 없습니다. 다시 시도해 주세요.",
  "visa.free_page_title": "무비자 및 도착 비자 국가",
  "visa.free_page_subtitle": "네팔 여권으로 사전 승인 비자 없이 입국할 수 있는 모든 목적지입니다.",
  "visa.free_disclaimer": "오픈소스 passport-index-dataset 프로젝트에서 수집했습니다. 비자 정책은 자주 변경되며 정확한 국적 규정에 따라 다를 수 있으므로, 항공편을 예약하기 전에 목적지의 공식 이민국 사이트에서 현재 정책을 확인하세요. 출발 전 온라인으로 신청해야 하는 국가를 찾으시나요? 바로 옆의 eVisa 탭을 확인하세요.",
  "visa.up_to": "최대",
  "visa.stay_varies": "체류 기간은 다를 수 있음",
  "visa.evisa_page_title": "전자비자 국가",
  "visa.evisa_page_subtitle": "출국 전 온라인으로 신청하세요 — 대사관 방문이나 사전 비자 스티커가 필요 없습니다.",
  "visa.evisa_disclaimer": "전자비자는 도착 비자와 다릅니다 — 여행 전에 온라인으로 신청하여 승인을 받아야 하며, 보통 며칠 전에 미리 진행해야 합니다. 오픈소스 passport-index-dataset 프로젝트에서 수집했습니다. 표시된 수수료와 처리 기간은 일반적인 참고 사항이므로, 항공편 예약 전 목적지의 공식 전자비자 포털에서 확인하세요. 아예 신청이 필요 없는 국가를 찾으시나요? 바로 옆의 무비자 및 도착 비자 탭을 확인하세요.",
  "visa.free_category_visa_free_title": "무비자",
