  "footer.affiliate_notice": "Himal to HorizonはTravelpayoutsのアフィリエイトパートナーです。リンクを通じた予約で手数料を得る場合があります。",
  "about.back": "ホーム",
  "about.hero_subtitle": "シンプルな不満から生まれたプロジェクト — フライト予約が第二の仕事のように感じられるべきではありません。",
  "about.creator_title": "こんにちは、Jiwanです",
  "about.creator_p1": "私はHimal to Horizon YouTubeチャンネルの旅行クリエイターJiwanです。チャンネルはリアルな旅行について — 協賛ホテルや演出された完璧さではなく、あなたや私のような普通の人々が世界をより賢く探索するのを助ける正直な旅行記です。",
  "about.creator_p2": "このツールは個人的な不満から作りました。複数のタブを何時間も行き来して最適な旅行時期を探していたとき、問題の見方が間違っていることに気づきました。日付を検索して価格が良いことを祈るのではなく、実際に滞在したい期間に基づいて最適な時期を教えてくれるツールがあったら？",
  "about.creator_p3": "それがStay Optimizer™となり、最終的にHimal to Horizonになりました — 一生懸命働き、慎重に貯蓄し、高い運賃に騙されることなく世界を見る資格がある普通の人々のために作られたサービスです。",
  "about.youtube_title": "YouTubeチャンネル",
  "about.youtube_desc": "Himal to Horizon YouTubeチャンネルは本物の旅行体験を共有する場所です — 生の、ありのままの、正直な旅行記。より賢く計画し、より自信を持って旅行するのに役立つ真実の物語。",
  "about.youtube_link": "YouTubeで見る",
  "about.photo_title": "写真",
  "about.photo_desc": "すべての目的地は光を通して物語を語ります。ヒマラヤの夜明けから大部分の観光客が素通りする都市の静かな街角まで、風景と旅行写真に情熱を持っています。",
  "about.mission_title": "ミッション",
  "about.mission_p1": "Himal to Horizonは私が「普通のジョー」と呼ぶ人々のために作られました — 一生懸命働き、慎重に貯蓄し、高い運賃に騙されたり決断に麻痺することなく世界を探検する資格がある人々。",
  "about.pillar_1_label": "最適な時期を見つける",
  "about.pillar_1_desc": "最安値の日付だけでなく — 価格、期間、柔軟性の最適な組み合わせ。",
  "about.pillar_2_label": "より多くの世界を旅する",
  "about.pillar_2_desc": "より良い価格のより長い滞在はより多くの国、より多くの経験、より多くの物語を意味します。",
  "about.pillar_3_label": "専門知識不要",
  "about.pillar_3_desc": "ここで作られたツールとインサイトは頻繁な旅行者がすでに知っているものです。今や誰もが利用できます。",
  "about.cta": "探索を始める",
  "about.cta_footer": "アカウント不要 · Travelpayouts提供運賃 · 普通のジョーのために♥で作成",
