  "hotels.title": "Horizonステイ",
  "hotels.desc": "ブティックゲストハウスからプレミアムリゾートまで。トップネットワークを比較して宿泊料金を節約。",
  "hotels.tips_title": "Horizonステイのヒント",
  "hotels.tip_1": "両パートナーで同じホテルを検索してください — 同じ部屋でも10〜20%の差がある場合があります。",
  "hotels.tip_2": "確認前に必ずキャンセルポリシーを確認してください。無料キャンセルは数ドル追加する価値があります。",
  "hotels.tip_3": "Agodaはアジアの宿泊施設でより低い価格を表示することが多く、Hotels.comは頻繁な予約者に報酬を与えます。",
  "hotels.tip_4": "現地通貨での予約はUSDでの予約より安くなる場合があります。",
