  "visa.difficulty_page_subtitle": "取り扱う全ての渡航先を、申請が簡単な順から難しい順に並べています。",
  "visa.difficulty_disclaimer": "これは要件の複雑さのランキングであり、承認率の統計ではありません。国籍別のビザ承認率を公表する入国管理当局はないため、私たちもそのようなデータを持っているとは主張しません。代わりに、このスコアは各国についてすでに調査した内容——申請方法、必要書類の数、無犯罪証明書や面接が実際に必要かどうか、処理に通常どれくらい時間がかかるか——から算出されています。「難しい」というランキングは書類や時間がより多く必要という意味であり、承認の可能性が低いという意味ではありません。",
