  "footer.affiliate_notice": "Himal to Horizon 是 Travelpayouts 的联盟合作伙伴。通过我们的链接预订，我们可能会赚取佣金。",
  "about.back": "主页",
  "about.hero_subtitle": "一个源于简单挫败感的项目 — 预订机票不应该感觉像第二份工作。",
  "about.creator_title": "嗨，我是Jiwan",
  "about.creator_p1": "我是Jiwan — Himal to Horizon YouTube频道背后的旅行创作者。我的频道关注真实旅行：没有赞助酒店套房或精心策划的完美，只是诚实的旅行，帮助像你我这样的普通人更聪明地探索世界。",
  "about.creator_p2": "我是出于个人挫败感建立这个工具的。我花了几个小时在多个标签页上寻找最佳飞行时机，才意识到我从错误的角度看待这个问题。与其搜索日期并希望价格合适，不如有一个工具能根据你实际想要停留的时间告诉你最佳窗口？",
  "about.creator_p3": "这成为了Stay Optimizer™，最终成为了Himal to Horizon — 专门为努力工作、谨慎储蓄、不被高价坑骗就能看到世界的普通人打造的服务。",
  "about.youtube_title": "YouTube频道",
  "about.youtube_desc": "Himal to Horizon YouTube频道是我分享真实旅行体验的地方 — 原始的、未经过滤的、诚实的。帮助你更聪明地规划和更自信地旅行的真实故事。",
  "about.youtube_link": "在YouTube上观看",
  "about.photo_title": "摄影",
  "about.photo_desc": "每个目的地通过光线讲述故事。我热衷于风景和旅行摄影 — 从喜马拉雅的黎明到大多数游客飞过的城市安静街景。",
  "about.mission_title": "使命",
  "about.mission_p1": "Himal to Horizon是为我所说的\"普通人\"而建的 — 那些努力工作、谨慎储蓄，应该能探索世界而不被高价欺骗或被决策瘫痪的人。",
  "about.pillar_1_label": "找到最佳时机",
  "about.pillar_1_desc": "不只是最便宜的日期 — 价格、时长和灵活性的最佳组合。",
  "about.pillar_2_label": "游览更多世界",
  "about.pillar_2_desc": "更好价格的更长停留意味着更多国家、更多体验、更多故事。",
  "about.pillar_3_label": "无需内部知识",
  "about.pillar_3_desc": "这里构建的工具和洞察是常飞旅客已经知道的。现在每个人都能使用。",
  "about.cta": "开始探索",
  "about.cta_footer": "无需账户 · Travelpayouts提供票价 · 为普通人用♥打造",
