  "hotels.title": "Horizon住宿",
  "hotels.desc": "从精品客栈到豪华度假村。我们比较顶级网络，让您不为房间多付钱。",
  "hotels.tips_title": "Horizon住宿技巧",
  "hotels.tip_1": "在两个合作伙伴上搜索同一酒店 — 即使是同一房间，价格也可能相差10–20%。",
  "hotels.tip_2": "确认前务必查看取消政策。免费取消值得多花几美元。",
  "hotels.tip_3": "Agoda通常为亚洲房产显示更低净价；Hotels.com对常客有奖励。",
  "hotels.tip_4": "用当地货币预订有时比用美元预订更便宜。",
  "hotels.agoda_title": "Agoda — 亚洲及更广区域的最佳选择",
  "hotels.agoda_desc": "亚洲、南美和全球枢纽酒店价格持续最低。全球200万+房源，即时确认，取消灵活。",
  "hotels.agoda_cta": "在Agoda搜索优惠",
  "hotels.hotelscom_desc": "非常适合北美旅行和灵活的取消政策。通过奖励计划每预订10晚赢得一晚免费住宿。",
  "hotels.hotelscom_cta": "在Hotels.com搜索",
  "hotels.klook_title": "Klook酒店和套餐",
  "hotels.klook_desc": "非常适合亚洲旅行或预订住宿+活动套餐。与房间和旅游一起预订时，Klook通常会提供独家折扣。",
  "hotels.klook_cta": "在Klook搜索酒店",
  "hotels.check_1": "检查免费取消截止日期（不仅仅是「免费取消」）",
  "hotels.check_2": "阅读最新评论 — 按日期排序，而不是评分",
  "hotels.check_3": "确认早餐和税费包含在价格中",
  "hotels.check_4": "如果您的航班早到，请询问早入住选项",
  "cars.title": "Horizon租车",
  "cars.desc": "跳过柜台排队和隐藏费用。选择我们的验证合作伙伴为您的行程找到最佳车辆。",
  "cars.how_title": "Horizon租车如何使用",
  "cars.step_1": "点击合作伙伴 — 您将直接进入他们的安全预订页面。",
  "cars.step_2": "按取车地点、日期和车型搜索。我们不添加隐藏费用。",
  "cars.step_3": "直接与合作伙伴预订。确认函直接发送给您。",
  "cars.step_4": "部分链接为联盟链接 — 我们赚取少量佣金，您无需额外付费。",
  "cars.localrent_title": "Localrent — 最佳本地优惠",
  "cars.localrent_desc": "支持当地商家，以更低的押金找到独特车辆。通常比大型连锁店便宜20-40%。",
  "cars.localrent_cta": "搜索Localrent",
