  "flights.hop2_title": "预订接驳",
  "flights.hop2_body": "确保了便宜的枢纽航班后，为最后一段预订单独的当地廉价航空或巴士。两张票之间至少留3小时。",
  "flights.hop3_title": "使用 Kiwi",
