  "visa.difficulty_page_title": "从易到难：旅游签证难度",
  "visa.difficulty_page_subtitle": "我们收录的所有目的地，按申请难易程度从易到难排序。",
  "visa.difficulty_disclaimer": "这是一个要求复杂度排名，而不是批准率统计。没有任何移民局会按国籍公布签证批准率，因此我们也不声称拥有此类数据。相反，该分数是根据我们已针对每个国家研究的内容计算得出的：申请方式、所需文件数量、是否确实需要无犯罪证明或面试，以及处理通常需要多长时间。“困难”排名意味着更多的文书工作和时间——而不是更低的批准几率。",
