  "home.cat_tips": "Reisetipps",
  "home.cat_story": "Reisegeschichte",
  "footer.affiliate_notice": "Himal to Horizon ist ein Affiliate-Partner von Travelpayouts. Wir verdienen möglicherweise eine Provision bei Buchungen über unsere Links.",
  "about.back": "Startseite",
  "about.hero_subtitle": "Ein Projekt aus einer einfachen Frustration — die Buchung von Flügen sollte sich nicht wie ein zweiter Job anfühlen.",
  "about.creator_title": "Hey, ich bin Jiwan",
  "about.creator_p1": "Ich bin Jiwan — der Reise-Creator hinter dem Himal to Horizon YouTube-Kanal. Mein Kanal dreht sich um echtes Reisen: keine gesponserten Hotelsuiten oder inszenierte Perfektion, nur ehrliche Reisen, die normalen Menschen — Menschen wie Ihnen und mir — helfen, die Welt klüger zu erkunden.",
  "about.creator_p2": "Dieses Tool habe ich aus persönlicher Frustration entwickelt. Ich verbrachte Stunden auf mehreren Tabs, um den besten Reisezeitraum zu finden, nur um festzustellen, dass ich das Problem falsch betrachtete. Anstatt ein Datum zu suchen und auf einen guten Preis zu hoffen, was wäre, wenn das Tool Ihnen das beste Fenster basierend auf Ihrem gewünschten Aufenthalt anzeigt?",
  "about.creator_p3": "Das wurde zum Stay Optimizer™ und schließlich zu Himal to Horizon — entwickelt speziell für normale Menschen, die hart arbeiten, umsichtig sparen und die Welt sehen sollten, ohne von überhöhten Tarifen abgezockt zu werden.",
  "about.youtube_title": "Der YouTube-Kanal",
  "about.youtube_desc": "Der Himal to Horizon YouTube-Kanal ist der Ort, wo ich echte Reiseerlebnisse teile — roh, ungefiltert und ehrlich. Echte Geschichten, die Ihnen helfen, klüger zu planen und selbstbewusster zu reisen.",
  "about.youtube_link": "Auf YouTube ansehen",
  "about.photo_title": "Fotografie",
  "about.photo_desc": "Jedes Reiseziel erzählt eine Geschichte durch Licht. Ich begeistere mich für Landschafts- und Reisefotografie — vom Himalaya-Morgengrauen bis zu stillen Straßenszenen in Städten, über die die meisten Touristen hinwegfliegen.",
  "about.mission_title": "Die Mission",
  "about.mission_p1": "Himal to Horizon ist für das gebaut, was ich 'normale Joes' nenne — Menschen, die hart arbeiten, umsichtig sparen und die Welt erkunden sollten, ohne von überhöhten Tarifen abgezockt oder durch Entscheidungslähmung gelähmt zu werden.",
  "about.pillar_1_label": "Das beste Fenster finden",
  "about.pillar_1_desc": "Nicht nur das günstigste Datum — die beste Kombination aus Preis, Dauer und Flexibilität.",
  "about.pillar_2_label": "Mehr von der Welt reisen",
  "about.pillar_2_desc": "Längere Aufenthalte zu besseren Preisen bedeuten mehr Länder, mehr Erlebnisse, mehr Geschichten.",
  "about.pillar_3_label": "Kein Insiderwissen erforderlich",
  "about.pillar_3_desc": "Die hier entwickelten Tools und Einblicke sind das, was Vielreisende bereits wissen. Jetzt haben alle Zugang.",
  "about.cta": "Erkunden Sie beginnen",
  "about.cta_footer": "Kein Konto erforderlich · Travelpayouts-betriebene Tarife · Mit ♥ für normale Joes entwickelt",
