  "hotels.title": "Horizon Unterkünfte",
  "hotels.desc": "Von Boutique-Gästehäusern bis zu Premium-Resorts. Wir vergleichen die Top-Netzwerke, damit Sie nicht zu viel für Ihr Zimmer bezahlen.",
  "hotels.tips_title": "Horizon Unterkünfte Tipps",
  "hotels.tip_1": "Suchen Sie dasselbe Hotel bei beiden Partnern — die Preise können für dasselbe Zimmer um 10–20% abweichen.",
  "hotels.tip_2": "Prüfen Sie immer die Stornierungsbedingungen, bevor Sie bestätigen. Kostenlose Stornierung ist ein paar Euro mehr wert.",
  "hotels.tip_3": "Agoda zeigt oft niedrigere Nettopreise für asiatische Unterkünfte; Hotels.com belohnt häufige Bucher.",
  "hotels.tip_4": "Die Buchung in lokaler Währung kann manchmal günstiger sein als in USD.",
  "hotels.agoda_title": "Agoda — Am besten für Asien und darüber hinaus",
  "hotels.agoda_desc": "Durchgehend die günstigsten Preise für Hotels in Asien, Südamerika und globalen Knotenpunkten. 2M+ Unterkünfte weltweit mit sofortiger Bestätigung.",
  "hotels.agoda_cta": "Angebote auf Agoda suchen",
  "hotels.hotelscom_desc": "Ideal für Nordamerikareisen und flexible Stornierungsbedingungen. Verdienen Sie eine Gratisnacht für je 10 gebuchte Nächte.",
  "hotels.hotelscom_cta": "Hotels.com durchsuchen",
  "hotels.klook_title": "Klook Hotels & Pakete",
  "hotels.klook_desc": "Ideal für Reisen in Asien oder Unterkunft + Erlebnis Kombibuchen. Klook bietet oft exklusive Rabatte beim gemeinsamen Buchen von Zimmer und Touren.",
  "hotels.klook_cta": "Hotels auf Klook suchen",
  "hotels.check_1": "Kostenlose Stornierungsfrist prüfen (nicht nur 'kostenlose Stornierung')",
  "hotels.check_2": "Aktuelle Bewertungen lesen — nach Datum sortieren, nicht nach Punktzahl",
