  "cars.title": "Horizon Mietwagen",
  "cars.desc": "Warteschlangen und versteckte Gebühren umgehen. Wählen Sie einen unserer verifizierten Partner, um die besten Fahrzeuge für Ihre Reise zu finden.",
  "cars.how_title": "So funktionieren Horizon Mietwagen",
