  "home.cat_trek": "Отчёт о треке",
  "home.cat_destination": "Путеводитель",
  "home.cat_tips": "Советы путешественникам",
  "home.cat_story": "История путешествия",
  "footer.affiliate_notice": "Himal to Horizon — партнёр Travelpayouts. Мы можем получать комиссию за бронирования по нашим ссылкам.",
  "about.back": "Главная",
  "about.hero_subtitle": "Проект, рождённый из простого разочарования — бронирование авиабилетов не должно ощущаться как вторая работа.",
  "about.creator_title": "Привет, я Дживан",
  "about.creator_p1": "Я Дживан — тревел-創作者YouTube-канала Himal to Horizon. Мой канал о настоящих путешествиях: никаких спонсорских отелей или идеализированных картинок, только честные рассказы, которые помогают обычным людям — таким же, как вы и я — исследовать мир умнее.",
  "about.creator_p2": "Я создал этот инструмент из личного разочарования. Я тратил часы на множестве вкладок, пытаясь найти лучшее время для полёта, и только потом понял, что смотрел на проблему неправильно. Вместо того чтобы искать дату и надеяться на хорошую цену, что если инструмент сам подскажет лучшее окно — исходя из того, сколько времени вы хотите провести там?",
  "about.creator_p3": "Это стало Stay Optimizer™ и в конечном итоге Himal to Horizon — созданным специально для обычных людей, которые усердно работают, разумно копят и заслуживают видеть мир, не переплачивая за билеты.",
  "about.youtube_title": "YouTube-канал",
  "about.youtube_desc": "YouTube-канал Himal to Horizon — это место, где я делюсь настоящим опытом путешествий — сырым, непредвзятым и честным. Настоящие истории, которые помогают вам планировать умнее и путешествовать увереннее.",
  "about.youtube_link": "Смотреть на YouTube",
  "about.photo_title": "Фотография",
  "about.photo_desc": "Каждое место назначения рассказывает историю через свет. Я увлечён пейзажной и тревел-фотографией — от рассвета над Гималаями до тихих улиц городов, над которыми большинство туристов просто пролетают.",
  "about.mission_title": "Миссия",
  "about.mission_p1": "Himal to Horizon создан для тех, кого я называю «обычными Джо» — людей, которые усердно работают, разумно копят и заслуживают исследовать мир, не переплачивая и не впадая в ступор при выборе.",
  "about.pillar_1_label": "Найти лучшее окно",
  "about.pillar_1_desc": "Не просто самую дешёвую дату — лучшую комбинацию цены, длительности и гибкости.",
  "about.pillar_2_label": "Путешествовать по миру больше",
  "about.pillar_2_desc": "Более длительные пребывания по лучшим ценам означают больше стран, больше впечатлений, больше историй.",
  "about.pillar_3_label": "Никаких инсайдерских знаний",
  "about.pillar_3_desc": "Инструменты и инсайты, созданные здесь — это то, что частые путешественники уже знают. Теперь они доступны каждому.",
  "about.cta": "Начать исследование",
