  "hotels.title": "Horizon Отели",
  "hotels.desc": "От бутик-гостевых домов до премиальных курортов. Мы сравниваем лучшие сети, чтобы вы не переплачивали за номер.",
  "hotels.tips_title": "Советы по Horizon Отелям",
  "hotels.tip_1": "Ищите один и тот же отель у обоих партнёров — цены могут отличаться на 10–20% даже за один номер.",
  "hotels.tip_2": "Всегда проверяйте политику отмены перед подтверждением. Бесплатная отмена стоит нескольких дополнительных долларов.",
  "hotels.tip_3": "Agoda часто показывает более низкие нетто-цены на азиатские объекты; Hotels.com вознаграждает частых бронирующих.",
  "hotels.tip_4": "Бронирование в местной валюте иногда может быть дешевле, чем в долларах.",
  "hotels.agoda_title": "Agoda — Лучший для Азии и не только",
  "hotels.agoda_desc": "Стабильно самые низкие цены на отели в Азии, Южной Америке и глобальных хабах. 2M+ объектов по всему миру с мгновенным подтверждением.",
  "hotels.agoda_cta": "Найти предложения на Agoda",
  "hotels.hotelscom_desc": "Отлично для путешествий по Северной Америке и гибкой политики отмены. Зарабатывайте бесплатную ночь за каждые 10 забронированных ночей.",
  "hotels.hotelscom_cta": "Поиск на Hotels.com",
  "hotels.klook_title": "Klook Отели и пакеты",
  "hotels.klook_desc": "Идеально для путешествий по Азии или бронирования пакетов Проживание + Активности. Klook часто предлагает эксклюзивные скидки при совместном бронировании.",
  "hotels.klook_cta": "Найти отели на Klook",
  "hotels.check_1": "Проверьте срок бесплатной отмены (не только «бесплатная отмена»)",
  "hotels.check_2": "Читайте последние отзывы — сортируйте по дате, а не по оценке",
