  "hotels.check_4": "Спросите о раннем заселении, если ваш рейс прилетает рано",
  "cars.title": "Horizon Аренда авто",
  "cars.desc": "Пропустите очереди на стойке и скрытые сборы. Выберите одного из наших проверенных партнёров для поиска лучшего транспорта для вашей поездки.",
  "cars.how_title": "Как работает Horizon Аренда авто",
  "cars.step_1": "Нажмите на партнёра — вы будете перенаправлены прямо на их защищённую страницу бронирования.",
  "cars.step_2": "Ищите по месту получения, датам и типу автомобиля. Никаких скрытых сборов от нас.",
  "cars.step_3": "Бронируйте напрямую с партнёром. Подтверждение придёт прямо к вам.",
  "cars.step_4": "Некоторые ссылки являются партнёрскими — мы получаем небольшую комиссию без дополнительных затрат для вас.",
  "cars.localrent_title": "Localrent — Лучший для местных предложений",
  "cars.localrent_desc": "Поддержите местный бизнес и найдите уникальные автомобили с меньшим залогом. Часто на 20–40% дешевле.",
