  "home.visa_hero_subtitle": "Wymagania krok po kroku, opłaty i oficjalne linki dla posiadaczy paszportu nepalskiego — zweryfikowane na podstawie źródeł rządowych i na bieżąco aktualizowane.",
  "home.visa_hero_cta_primary": "Sprawdź moje wymagania wizowe",
