  "home.trust_refresh": "Aktualizowane co tydzień",
  "home.offer_community_title": "Społeczność podróżników",
  "home.offer_community_desc": "Prawdziwe historie i szczere rekomendacje od nepalskich podróżników — jedzenie, noclegi i ukryte perełki.",
  "home.offer_community_cta": "Odkryj historie",
  "footer.contact": "Skontaktuj się z nami",
  "footer.flights_link": "Loty",
  "home.cat_trek": "Raport z Treku",
