  "home.cat_tips": "Porady Podróżnicze",
  "home.cat_story": "Historia Podróży",
  "footer.affiliate_notice": "Himal to Horizon jest partnerem afiliacyjnym Travelpayouts. Możemy otrzymać prowizję od rezerwacji dokonanych za pośrednictwem naszych linków.",
  "about.back": "Strona główna",
  "about.hero_subtitle": "Projekt urodzony z prostej frustracji — rezerwacja lotów nie powinna być jak druga praca.",
  "about.creator_title": "Cześć, jestem Jiwan",
  "about.creator_p1": "Jestem Jiwan — twórca podróżniczy stojący za kanałem YouTube Himal to Horizon. Mój kanał dotyczy prawdziwych podróży: bez sponsorowanych apartamentów hotelowych czy wyreżyserowanej perfekcji, tylko uczciwe opowieści pomagające zwykłym ludziom — takim jak ty i ja — mądrzej odkrywać świat.",
  "about.creator_p2": "Stworzyłem to narzędzie z osobistej frustracji. Spędzałem godziny na wielu zakładkach, próbując znaleźć najlepszy czas na lot, żeby zdać sobie sprawę, że patrzyłem na problem w zły sposób. Zamiast szukać daty i mieć nadzieję, że cena będzie dobra, co by było, gdyby narzędzie powiedziało ci najlepsze okno — na podstawie tego, jak długo chcesz zostać?",
  "about.creator_p3": "To stało się Stay Optimizer™ i ostatecznie Himal to Horizon — zbudowany specjalnie dla zwykłych ludzi, którzy ciężko pracują, oszczędzają mądrze i zasługują na zobaczenie świata bez przepłacania.",
  "about.youtube_title": "Kanał YouTube",
  "about.youtube_desc": "Kanał YouTube Himal to Horizon to miejsce, gdzie dzielę się prawdziwymi doświadczeniami podróżniczymi — surowe, niefiltrowane i uczciwe. Prawdziwe historie, które pomagają ci planować mądrzej i podróżować pewniej.",
  "about.youtube_link": "Oglądaj na YouTube",
  "about.photo_title": "Fotografia",
  "about.photo_desc": "Każde miejsce docelowe opowiada historię przez światło. Pasjonuję się fotografią krajobrazową i podróżniczą — od himalajskiego świtu po ciche sceny uliczne w miastach, nad którymi większość turystów po prostu przelatuje.",
  "about.mission_title": "Misja",
  "about.mission_p1": "Himal to Horizon jest zbudowany dla tych, których nazywam 'zwykłymi Joe' — ludzi, którzy ciężko pracują, mądrze oszczędzają i zasługują na odkrywanie świata bez przepłacania i paraliżu decyzyjnego.",
  "about.pillar_1_label": "Znajdź najlepsze okno",
  "about.pillar_1_desc": "Nie tylko najtańsza data — najlepsza kombinacja ceny, czasu trwania i elastyczności.",
  "about.pillar_2_label": "Podróżuj po więcej świata",
  "about.pillar_2_desc": "Dłuższe pobyty za lepsze ceny oznaczają więcej krajów, więcej doświadczeń, więcej historii.",
  "about.pillar_3_label": "Nie potrzeba wiedzy insajdera",
  "about.pillar_3_desc": "Narzędzia i wskazówki zbudowane tutaj to te, które częste latający już znają. Teraz każdy je ma.",
  "about.cta": "Zacznij odkrywać",
  "about.cta_footer": "Nie potrzeba konta · Taryfy zasilane przez Travelpayouts · Zbudowany z ♥ dla zwykłych ludzi",
  "visa.title": "Przewodniki wizowe",
  "visa.subtitle": "Proste informacje wizowe dla popularnych kierunków — bez prawniczego żargonu. Sprawdź wymagania wjazdu przed rezerwacją.",
  "visa.disclaimer": "Informacje służą wyłącznie jako ogólny przewodnik. Zawsze sprawdzaj oficjalne źródła ambasad przed podróżą.",
