  "hotels.title": "Horizon Pobyty",
  "hotels.desc": "Od butikowych pensjonatów po ekskluzywne resorty. Porównujemy najlepsze sieci, żebyś nie przepłacał za pokój.",
  "hotels.tips_title": "Wskazówki Horizon Pobyty",
  "hotels.tip_1": "Szukaj tego samego hotelu u obu partnerów — ceny mogą się różnić o 10–20% nawet za ten sam pokój.",
  "hotels.tip_2": "Zawsze sprawdzaj politykę anulowania przed potwierdzeniem. Bezpłatne anulowanie jest warte kilku dodatkowych dolarów.",
  "hotels.tip_3": "Agoda często pokazuje niższe ceny netto dla azjatyckich obiektów; Hotels.com nagradza częste rezerwacje.",
  "hotels.tip_4": "Rezerwacja w lokalnej walucie może być tańsza niż w dolarach.",
  "hotels.agoda_title": "Agoda — Najlepszy dla Azji i nie tylko",
  "hotels.agoda_desc": "Stale najniższe ceny hoteli w Azji, Ameryce Południowej i globalnych centrach. Ponad 2 mln obiektów na całym świecie z natychmiastowym potwierdzeniem.",
  "hotels.agoda_cta": "Szukaj ofert na Agoda",
  "hotels.hotelscom_desc": "Świetny do podróży po Ameryce Północnej i elastycznych zasad anulowania. Zdobądź bezpłatną noc za każde 10 zarezerwowanych nocy.",
  "hotels.hotelscom_cta": "Szukaj na Hotels.com",
  "hotels.klook_title": "Klook Hotele i pakiety",
  "hotels.klook_desc": "Idealny do podróży po Azji lub rezerwacji pakietów Nocleg + Atrakcje. Klook często oferuje ekskluzywne rabaty przy łącznej rezerwacji pokoju i wycieczek.",
  "hotels.klook_cta": "Szukaj hoteli na Klook",
  "hotels.check_1": "Sprawdź termin bezpłatnego anulowania (nie tylko 'bezpłatne anulowanie')",
  "hotels.check_2": "Czytaj najnowsze recenzje — sortuj według daty, nie oceny",
  "hotels.check_3": "Upewnij się, że śniadanie i podatki są wliczone w cenę",
  "hotels.check_4": "Zapytaj o wcześniejszy meldunek, jeśli Twój lot przylatuje wcześnie",
  "cars.title": "Horizon Wynajem samochodów",
  "cars.desc": "Pomiń kolejki przy ladzie i ukryte opłaty. Wybierz jednego z naszych zweryfikowanych partnerów, aby znaleźć najlepsze pojazdy na swoją podróż.",
  "cars.how_title": "Jak działa Horizon Wynajem samochodów",
  "cars.step_1": "Kliknij partnera — zostaniesz przeniesiony bezpośrednio na jego bezpieczną stronę rezerwacji.",
  "cars.step_2": "Szukaj według miejsca odbioru, dat i rodzaju samochodu. Żadnych ukrytych opłat z naszej strony.",
  "cars.step_3": "Zarezerwuj bezpośrednio z partnerem. Potwierdzenie trafi prosto do ciebie.",
  "cars.step_4": "Niektóre linki są linkami partnerskimi — zarabiamy małą prowizję bez dodatkowych kosztów dla ciebie.",
  "cars.localrent_title": "Localrent — Najlepszy na lokalne oferty",
  "cars.localrent_desc": "Wspieraj lokalne firmy i znajdź unikalne pojazdy z niższymi kaucjami. Często 20–40% taniej.",
  "cars.localrent_cta": "Szukaj w Localrent",
  "cars.klook_title": "Wynajem samochodów Klook",
  "cars.klook_desc": "Idealny do odbioru na lotniskach i głównych marek. Porównaj najlepsze floty bez ukrytych opłat.",
  "cars.klook_cta": "Szukaj aut na Klook",
  "cars.economy_title": "EconomyBookings (Najlepszy na duże lotniska)",
  "cars.economy_desc": "Nasza najlepsza rekomendacja na lotniska. Porównuje wszystkie marki, aby znaleźć najniższą stawkę.",
  "cars.economy_cta": "Porównaj globalne stawki",
  "cars.getrentacar_title": "GetRentacar (Oferty bezpośrednie)",
  "cars.getrentacar_desc": "Wynajmuj bezpośrednio od lokalnych właścicieli. Fantastyczna alternatywa dla unikowych pojazdów.",
  "cars.getrentacar_cta": "Szukaj lokalnych właścicieli",
  "cars.checklist_title": "Lista kontrolna",
  "cars.check_1": "Zabierz prawo jazdy + MDP jeśli wymagane",
  "cars.check_2": "Sfotografuj samochód przed odjazdem",
  "cars.check_3": "Sprawdź politykę paliwową (pełny do pełnego)",
  "cars.check_4": "Potwierdź podróże transgraniczne",
  "insurance.title": "Horizon Shield",
  "insurance.desc": "Podróżuj ze spokojem ducha. Kompleksowe ubezpieczenie dla twojej następnej przygody — od dowodu wizowego po pełną ochronę anulowania podróży.",
  "insurance.badge_top_pick": "Najlepszy wybór",
  "insurance.badge_live": "Aktywne",
  "insurance.ekta_title": "Ubezpieczenie EKTA",
  "insurance.ekta_desc": "Ubezpieczenie podróżne zgodne z wizą dla Schengen, UK i świata. Natychmiastowy PDF.",
  "insurance.ekta_cta": "Uzyskaj ochronę EKTA",
  "insurance.klook_title": "Ubezpieczenie podróżne Klook",
  "insurance.klook_desc": "Przeglądaj jednorazowe i roczne plany ubezpieczenia podróżnego na Klook — ochrona medyczna, odwołanie podróży i bagażu od zaufanej globalnej platformy rezerwacyjnej.",
  "insurance.klook_cta": "Zobacz ubezpieczenie na Klook",
  "insurance.vc_desc": "Budżetowe plany z całodobową pomocą kryzysową.",
  "insurance.vc_cta": "Porównaj plany",
  "insurance.why_title": "Dlaczego ubezpieczenie podróżne jest ważne",
