  "about.hero_subtitle": "Projekti syntyi yksinkertaisesta turhautumisesta — lentojen varaamisen ei pitäisi tuntua toiselta työtä.",
  "about.creator_title": "Hei, olen Jiwan",
  "about.creator_p1": "Olen Jiwan — matkailuluoja Himal to Horizon YouTube -kanavan takana. Kanavani käsittelee oikeaa matkailua: ei sponsoroituja hotellihuoneistoja tai kuratoitua täydellisyyttä, vain rehellisiä matkoja, jotka auttavat tavallisia ihmisiä — sinun ja minun kaltaisiani — tutkimaan maailmaa älykkäämmin.",
  "about.creator_p2": "Rakensin tämän työkalun henkilökohtaisesta turhautumisesta. Vietin tunteja useilla välilehdillä yrittäen löytää parasta aikaa lentää jonnekin, vain huomatakseni, että katsoin ongelmaa väärästä kulmasta. Sen sijaan, että etsii päivämäärää ja toivoo hyvää hintaa, entä jos työkalu kertoisi sinulle parhaan ikkunan — sen perusteella, kuinka kauan haluat oikeasti pysyä?",
  "about.creator_p3": "Siitä tuli Stay Optimizer™ ja lopulta Himal to Horizon — rakennettu erityisesti tavallisille ihmisille, jotka työskentelevät kovasti, säästävät harkiten ja ansaitsevat nähdä maailman ilman ylihinnoiteltuja lippuja.",
  "about.youtube_title": "YouTube-kanava",
  "about.youtube_desc": "Himal to Horizon YouTube -kanava on paikka, jossa jaan oikeita matkakokemuksia — raakoja, suodattamattomia ja rehellisiä. Todellisia tarinoita, jotka auttavat sinua suunnittelemaan älykkäämmin ja matkustamaan luottavaisemmin.",
  "about.youtube_link": "Katso YouTubessa",
  "about.photo_title": "Valokuvaus",
  "about.photo_desc": "Jokainen kohde kertoo tarinan valon kautta. Olen intohimoinen maisema- ja matkailukuvaamisesta — Himalajan aamunsarastuksesta hiljaisiin katukuviin kaupungeissa, joiden yli useimmat turistit vain lentävät.",
  "about.mission_title": "Missio",
  "about.mission_p1": "Himal to Horizon on rakennettu niille, joita kutsun 'tavallisiksi Joeiksi' — ihmisille, jotka työskentelevät kovasti, säästävät harkiten ja ansaitsevat tutkia maailmaa ilman ylihinnoittelua tai päätöslamaantumista.",
  "about.pillar_1_label": "Löydä paras ikkuna",
  "about.pillar_1_desc": "Ei vain halvin päivämäärä — paras yhdistelmä hintaa, kestoa ja joustavuutta.",
  "about.pillar_2_label": "Matkusta enemmän maailmaa",
  "about.pillar_2_desc": "Pidemmät oleskelu parempiin hintoihin tarkoittaa enemmän maita, enemmän kokemuksia, enemmän tarinoita.",
  "about.pillar_3_label": "Ei sisäpiiritietoa tarvita",
  "about.pillar_3_desc": "Täällä rakennetut työkalut ja vinkit ovat niitä, joita tiheästi lentävät jo tietävät. Nyt kaikilla on ne.",
  "about.cta": "Aloita tutkiminen",
  "about.cta_footer": "Ei tiliä tarvita · Travelpayouts-käytteiset hinnat · Rakennettu ♥:llä tavallisille Joeille",
