  "hotels.title": "Horizon-yöpymiset",
  "hotels.desc": "Boutique-vierashuoneista premium-lomakohteisiin. Vertailemme parhaat verkostot, jotta et maksa liikaa huoneestasi.",
  "hotels.tips_title": "Horizon-yöpymisten vinkit",
  "hotels.tip_1": "Etsi samaa hotellia molemmilta kumppaneilta — hinnat voivat erota 10–20% jopa samassa huoneessa.",
  "hotels.tip_2": "Tarkista aina peruutuskäytäntö ennen vahvistamista. Ilmainen peruutus on muutaman euron arvoinen.",
