  "home.cat_story": "Reseberättelse",
  "footer.affiliate_notice": "Himal to Horizon är en affiliate-partner till Travelpayouts. Vi kan tjäna provision på bokningar via våra länkar.",
  "about.back": "Startsida",
  "about.hero_subtitle": "Ett projekt fött ur en enkel frustration — att boka flyg ska inte kännas som ett andra jobb.",
  "about.creator_title": "Hej, jag är Jiwan",
  "about.creator_p1": "Jag är Jiwan — resekonstnären bakom Himal to Horizon YouTube-kanalen. Min kanal handlar om verkliga resor: inga sponsrade hotellsviter eller kurerad perfektion, bara ärliga resor som hjälper vanliga människor — som du och jag — att utforska världen smartare.",
  "about.creator_p2": "Jag byggde det här verktyget av personlig frustration. Jag spenderade timmar på flera flikar för att hitta den bästa tiden att flyga någonstans, för att bara inse att jag tittade på problemet fel. Istället för att söka ett datum och hoppas att priset är bra, tänk om verktyget berättade det bästa fönstret — baserat på hur länge du faktiskt vill stanna?",
  "about.creator_p3": "Det blev Stay Optimizer™ och slutligen Himal to Horizon — byggt specifikt för vanliga människor som arbetar hårt, sparar klokt och förtjänar att se världen utan att bli lurade av uppblåsta priser.",
  "about.youtube_title": "YouTube-kanalen",
  "about.youtube_desc": "Himal to Horizon YouTube-kanalen är där jag delar verkliga reseupplevelser — råa, ofiltrerade och ärliga. Riktiga berättelser som hjälper dig att planera smartare och resa mer säkert.",
  "about.youtube_link": "Titta på YouTube",
  "about.photo_title": "Fotografi",
  "about.photo_desc": "Varje destination berättar en historia genom ljus. Jag är passionerad om landsskaps- och resefotografi — från himalayaisk gryning till tysta gatubilder i städer som de flesta turister flyger över.",
  "about.mission_title": "Uppdraget",
  "about.mission_p1": "Himal to Horizon är byggt för det jag kallar 'vanliga Joe' — människor som arbetar hårt, sparar klokt och förtjänar att utforska världen utan att bli lurade av uppblåsta priser eller förlamade av beslutsångest.",
  "about.pillar_1_label": "Hitta det bästa fönstret",
  "about.pillar_1_desc": "Inte bara det billigaste datumet — den bästa kombinationen av pris, varaktighet och flexibilitet.",
  "about.pillar_2_label": "Res mer av världen",
  "about.pillar_2_desc": "Längre vistelser till bättre priser innebär fler länder, fler upplevelser, fler berättelser.",
  "about.pillar_3_label": "Ingen insiderkunskap behövs",
  "about.pillar_3_desc": "Verktygen och tipsen som byggts här är de som frekventa resenärer redan vet. Nu har alla dem.",
  "about.cta": "Börja utforska",
  "about.cta_footer": "Inget konto behövs · Travelpayouts-drivna priser · Byggt med ♥ för vanliga Joes",
  "visa.title": "Visumguider",
  "visa.subtitle": "Enkel visuminformation för populära destinationer — inget juridiskt språk. Kolla inresekraven innan du bokar.",
  "visa.disclaimer": "Information är enbart för allmän vägledning. Kontrollera alltid officiella ambassadkällor innan du reser.",
