  "footer.affiliate_notice": "Himal to Horizon er en affiliate-partner med Travelpayouts. Vi kan tjene provisjon på bestillinger via lenkene våre.",
  "about.back": "Hjem",
  "about.hero_subtitle": "Et prosjekt født av en enkel frustrasjon — å bestille fly burde ikke føles som en andre jobb.",
  "about.creator_title": "Hei, jeg er Jiwan",
  "about.creator_p1": "Jeg er Jiwan — reiseskaperen bak Himal to Horizon YouTube-kanalen. Kanalen min handler om ekte reiser: ingen sponsede hotellsuiter eller kuratert perfeksjon, bare ærlige reiser som hjelper vanlige mennesker — som deg og meg — å utforske verden smartere.",
  "about.creator_p2": "Jeg bygde dette verktøyet av personlig frustrasjon. Jeg brukte timer på flere faner for å finne den beste tiden å fly til et sted, bare for å innse at jeg så på problemet feil. Istedenfor å søke etter en dato og håpe at prisen er bra, hva om verktøyet fortalte deg det beste vinduet — basert på hvor lenge du faktisk vil bli?",
  "about.creator_p3": "Det ble Stay Optimizer™ og til slutt Himal to Horizon — bygd spesifikt for vanlige mennesker som jobber hardt, sparer fornuftig og fortjener å se verden uten å bli lurt av oppblåste priser.",
  "about.youtube_title": "YouTube-kanalen",
  "about.youtube_desc": "Himal to Horizon YouTube-kanalen er der jeg deler ekte reiseopplevelser — rå, ufiltrerte og ærlige. Ekte historier som hjelper deg å planlegge smartere og reise mer trygt.",
  "about.youtube_link": "Se på YouTube",
  "about.photo_title": "Fotografering",
  "about.photo_desc": "Hvert reisemål forteller en historie gjennom lys. Jeg er lidenskapelig opptatt av landskap- og reisefotografering — fra himalayansk daggry til stille gatebilder i byer de fleste turister bare flyr over.",
  "about.mission_title": "Oppdraget",
  "about.mission_p1": "Himal to Horizon er bygd for det jeg kaller 'vanlige Joer' — mennesker som jobber hardt, sparer fornuftig og fortjener å utforske verden uten å bli lurt av oppblåste priser eller lammet av beslutningsvansker.",
  "about.pillar_1_label": "Finn det beste vinduet",
  "about.pillar_1_desc": "Ikke bare den billigste datoen — den beste kombinasjonen av pris, varighet og fleksibilitet.",
  "about.pillar_2_label": "Reis mer av verden",
  "about.pillar_2_desc": "Lengre opphold til bedre priser betyr flere land, flere opplevelser, flere historier.",
  "about.pillar_3_label": "Ingen insiderkunnskap nødvendig",
  "about.pillar_3_desc": "Verktøyene og tipsene som er bygd her er de som hyppige reisende allerede kjenner. Nå har alle dem.",
  "about.cta": "Begynn å utforske",
  "about.cta_footer": "Ingen konto nødvendig · Travelpayouts-drevne priser · Bygd med ♥ for vanlige Joer",
