  "hotels.title": "Horizon Opphold",
  "hotels.desc": "Fra boutique-gjestehus til premiumresorts. Vi sammenligner toppnettverkene slik at du ikke betaler for mye for rommet ditt.",
  "hotels.tips_title": "Horizon Opphold tips",
  "hotels.tip_1": "Søk samme hotell hos begge partnere — prisene kan variere med 10–20% selv for samme rom.",
  "hotels.tip_2": "Sjekk alltid avbestillingspolicyen før du bekrefter. Gratis avbestilling er verdt noen ekstra dollar.",
  "hotels.tip_3": "Agoda viser ofte lavere nettopriser for asiatiske eiendommer; Hotels.com belønner hyppige bestillere.",
  "hotels.tip_4": "Bestilling i lokal valuta kan noen ganger være billigere enn i USD.",
  "hotels.agoda_title": "Agoda — Best for Asia og videre",
  "hotels.agoda_desc": "Konsekvent laveste priser for hoteller i Asia, Sør-Amerika og globale knutepunkter. 2M+ eiendommer over hele verden med umiddelbar bekreftelse.",
  "hotels.agoda_cta": "Søk tilbud på Agoda",
  "hotels.hotelscom_desc": "Flott for reiser i Nord-Amerika og fleksible avbestillingsbetingelser. Tjen en gratis natt for hver 10 netter bestilt.",
  "hotels.hotelscom_cta": "Søk på Hotels.com",
  "hotels.klook_title": "Klook Hoteller & Pakker",
  "hotels.klook_desc": "Perfekt for reiser i Asia eller bestilling av Overnatting + Aktiviteter pakker. Klook tilbyr ofte eksklusive rabatter ved felles bestilling av rom og turer.",
  "hotels.klook_cta": "Søk hoteller på Klook",
  "hotels.check_1": "Sjekk fristen for gratis avbestilling (ikke bare 'gratis avbestilling')",
  "hotels.check_2": "Les nylige anmeldelser — sorter etter dato, ikke score",
  "hotels.check_3": "Bekreft at frokost og skatter er inkludert i prisen",
  "hotels.check_4": "Spør om tidlig innsjekking hvis flyet ditt ankommer tidlig",
  "cars.title": "Horizon Bilutleie",
  "cars.desc": "Hopp over skrankekøene og skjulte avgifter. Velg en av våre verifiserte partnere for å finne de beste kjøretøyene for turen din.",
