  "footer.flights_link": "Chuyến bay",
  "home.cat_trek": "Báo cáo Trekking",
  "home.cat_destination": "Hướng dẫn Điểm đến",
  "home.cat_tips": "Mẹo Du lịch",
  "home.cat_story": "Câu chuyện Du lịch",
  "footer.affiliate_notice": "Himal to Horizon là đối tác liên kết của Travelpayouts. Chúng tôi có thể kiếm hoa hồng từ các đặt chỗ qua liên kết của chúng tôi.",
  "about.back": "Trang chủ",
  "about.hero_subtitle": "Một dự án ra đời từ sự thất vọng đơn giản — đặt vé máy bay không nên cảm thấy như công việc thứ hai.",
  "about.creator_title": "Xin chào, tôi là Jiwan",
  "about.creator_p1": "Tôi là Jiwan — người tạo nội dung du lịch đằng sau kênh YouTube Himal to Horizon. Kênh của tôi về du lịch thực sự: không có phòng khách sạn được tài trợ hay sự hoàn hảo được dàn dựng, chỉ là những hành trình trung thực giúp những người bình thường — như bạn và tôi — khám phá thế giới thông minh hơn.",
  "about.creator_p2": "Tôi xây dựng công cụ này vì sự thất vọng cá nhân. Tôi dành hàng giờ trên nhiều tab cố gắng tìm thời điểm tốt nhất để bay đến đâu đó, chỉ để nhận ra rằng tôi đang nhìn vào vấn đề theo cách sai. Thay vì tìm kiếm một ngày và hy vọng giá tốt, thì sao nếu công cụ cho bạn biết cửa sổ tốt nhất — dựa trên việc bạn thực sự muốn ở lại bao lâu?",
  "about.creator_p3": "Đó trở thành Stay Optimizer™, và cuối cùng là Himal to Horizon — được xây dựng dành riêng cho những người bình thường làm việc chăm chỉ, tiết kiệm thận trọng và xứng đáng được nhìn thấy thế giới mà không bị lừa bởi giá vé bị thổi phồng.",
  "about.youtube_title": "Kênh YouTube",
  "about.youtube_desc": "Kênh YouTube Himal to Horizon là nơi tôi chia sẻ những trải nghiệm du lịch thực sự — thô, không được lọc và trung thực. Những câu chuyện thực sự giúp bạn lập kế hoạch thông minh hơn và du lịch tự tin hơn.",
  "about.youtube_link": "Xem trên YouTube",
  "about.photo_title": "Nhiếp ảnh",
  "about.photo_desc": "Mỗi điểm đến kể một câu chuyện qua ánh sáng. Tôi đam mê nhiếp ảnh phong cảnh và du lịch — từ bình minh Himalaya đến những cảnh phố yên tĩnh ở các thành phố mà hầu hết khách du lịch chỉ bay qua.",
  "about.mission_title": "Sứ mệnh",
  "about.mission_p1": "Himal to Horizon được xây dựng cho những người tôi gọi là 'Joes bình thường' — những người làm việc chăm chỉ, tiết kiệm thận trọng và xứng đáng khám phá thế giới mà không bị lừa bởi giá vé bị thổi phồng hay bị tê liệt vì phân vân.",
  "about.pillar_1_label": "Tìm cửa sổ tốt nhất",
  "about.pillar_1_desc": "Không chỉ là ngày rẻ nhất — sự kết hợp tốt nhất giữa giá, thời gian và tính linh hoạt.",
  "about.pillar_2_label": "Du lịch nhiều hơn thế giới",
  "about.pillar_2_desc": "Lưu trú dài hơn với giá tốt hơn có nghĩa là nhiều quốc gia hơn, nhiều trải nghiệm hơn, nhiều câu chuyện hơn.",
  "about.pillar_3_label": "Không cần kiến thức nội bộ",
  "about.pillar_3_desc": "Các công cụ và gợi ý được xây dựng ở đây là những gì người thường xuyên bay đã biết. Bây giờ mọi người đều có chúng.",
  "about.cta": "Bắt đầu khám phá",
  "about.cta_footer": "Không cần tài khoản · Giá vé do Travelpayouts cung cấp · Được xây dựng với ♥ cho Joes bình thường",
