  "hotels.title": "Horizon Lưu trú",
  "hotels.desc": "Từ nhà khách boutique đến khu nghỉ dưỡng cao cấp. Chúng tôi so sánh các mạng lưới hàng đầu để bạn không trả thêm cho phòng.",
  "hotels.tips_title": "Mẹo Horizon Lưu trú",
  "hotels.tip_1": "Tìm kiếm cùng một khách sạn trên cả hai đối tác — giá có thể khác nhau 10–20% ngay cả cho cùng một phòng.",
  "hotels.tip_2": "Luôn kiểm tra chính sách hủy trước khi xác nhận. Hủy miễn phí đáng để trả thêm vài đô.",
  "hotels.tip_3": "Agoda thường hiển thị giá ròng thấp hơn cho các tài sản châu Á; Hotels.com thưởng cho người đặt thường xuyên.",
