  "footer.affiliate_notice": "Himal to Horizon เป็นพาร์ทเนอร์พันธมิตรของ Travelpayouts เราอาจได้รับค่าคอมมิชชั่นจากการจองผ่านลิงก์ของเรา",
  "about.back": "หน้าหลัก",
  "about.hero_subtitle": "โปรเจ็กต์ที่เกิดจากความหงุดหงิดง่ายๆ — การจองเที่ยวบินไม่ควรรู้สึกเหมือนงานที่สอง",
  "about.creator_title": "สวัสดี ฉันชื่อ Jiwan",
  "about.creator_p1": "ฉันคือ Jiwan — ผู้สร้างเนื้อหาการเดินทางเบื้องหลังช่อง YouTube Himal to Horizon ช่องของฉันเกี่ยวกับการเดินทางจริงๆ: ไม่มีห้องโรงแรมที่ได้รับการสนับสนุนหรือความสมบูรณ์แบบที่ถูกจัดฉาก มีแค่การเดินทางที่ซื่อสัตย์ที่ช่วยคนธรรมดา — อย่างคุณและฉัน — สำรวจโลกอย่างชาญฉลาดขึ้น",
  "about.creator_p2": "ฉันสร้างเครื่องมือนี้จากความหงุดหงิดส่วนตัว ฉันใช้เวลาหลายชั่วโมงบนแท็บหลายๆ แท็บพยายามหาเวลาที่ดีที่สุดในการบินไปที่ไหนสักที่ เพียงเพื่อตระหนักว่าฉันมองปัญหาในทางที่ผิด แทนที่จะค้นหาวันที่และหวังว่าราคาจะดี จะเป็นอย่างไรถ้าเครื่องมือบอกคุณถึงหน้าต่างที่ดีที่สุด — ตามระยะเวลาที่คุณต้องการอยู่จริงๆ",
  "about.creator_p3": "นั่นกลายเป็น Stay Optimizer™ และในที่สุดก็คือ Himal to Horizon — สร้างขึ้นโดยเฉพาะสำหรับคนธรรมดาที่ทำงานหนัก ออมอย่างรอบคอบ และสมควรที่จะเห็นโลกโดยไม่ถูกหลอกด้วยราคาที่บวมเกิน",
  "about.youtube_title": "ช่อง YouTube",
  "about.youtube_desc": "ช่อง YouTube Himal to Horizon คือที่ที่ฉันแบ่งปันประสบการณ์การเดินทางจริงๆ — ดิบ ไม่ผ่านการกรอง และซื่อสัตย์ เรื่องราวจริงที่ช่วยให้คุณวางแผนอย่างชาญฉลาดขึ้นและเดินทางอย่างมั่นใจมากขึ้น",
  "about.youtube_link": "ดูบน YouTube",
  "about.photo_title": "การถ่ายภาพ",
  "about.photo_desc": "ทุกจุดหมายเล่าเรื่องผ่านแสง ฉันหลงใหลในการถ่ายภาพภูมิทัศน์และการเดินทาง — จากรุ่งอรุณของหิมาลัยไปจนถึงฉากถนนที่เงียบสงบในเมืองที่นักท่องเที่ยวส่วนใหญ่เพียงแค่บินผ่าน",
  "about.mission_title": "พันธกิจ",
  "about.mission_p1": "Himal to Horizon สร้างขึ้นสำหรับสิ่งที่ฉันเรียกว่า 'Joe ธรรมดา' — คนที่ทำงานหนัก ออมอย่างรอบคอบ และสมควรที่จะสำรวจโลกโดยไม่ถูกหลอกด้วยราคาที่บวมเกินหรือเป็นอัมพาตจากการตัดสินใจ",
  "about.pillar_1_label": "ค้นหาหน้าต่างที่ดีที่สุด",
  "about.pillar_1_desc": "ไม่ใช่แค่วันที่ถูกที่สุด — การผสมผสานที่ดีที่สุดของราคา ระยะเวลา และความยืดหยุ่น",
  "about.pillar_2_label": "เดินทางท่องโลกให้มากขึ้น",
  "about.pillar_2_desc": "การพักนานขึ้นในราคาที่ดีกว่าหมายถึงประเทศมากขึ้น ประสบการณ์มากขึ้น เรื่องราวมากขึ้น",
  "about.pillar_3_label": "ไม่ต้องการความรู้ภายใน",
  "about.pillar_3_desc": "เครื่องมือและเคล็ดลับที่สร้างขึ้นที่นี่คือสิ่งที่นักเดินทางบ่อยๆ รู้อยู่แล้ว ตอนนี้ทุกคนมีมัน",
  "about.cta": "เริ่มสำรวจ",
