  "hotels.title": "Horizon ที่พัก",
  "hotels.desc": "จากเกสต์เฮาส์บูติกไปจนถึงรีสอร์ทพรีเมียม เราเปรียบเทียบเครือข่ายชั้นนำเพื่อให้คุณไม่ต้องจ่ายเกินสำหรับห้องพัก",
  "hotels.tips_title": "เคล็ดลับ Horizon ที่พัก",
  "hotels.tip_1": "ค้นหาโรงแรมเดียวกันกับพาร์ทเนอร์ทั้งสอง — ราคาอาจแตกต่างกัน 10–20% แม้แต่สำหรับห้องเดียวกัน",
  "hotels.tip_2": "ตรวจสอบนโยบายการยกเลิกก่อนยืนยันเสมอ การยกเลิกฟรีมีค่าสักสองสามดอลลาร์เพิ่ม",
  "hotels.tip_3": "Agoda มักแสดงราคาสุทธิที่ต่ำกว่าสำหรับทรัพย์สินในเอเชีย Hotels.com มอบรางวัลให้กับผู้จองบ่อยๆ",
  "hotels.tip_4": "การจองด้วยสกุลเงินท้องถิ่นอาจถูกกว่าการจองด้วย USD",
  "hotels.agoda_title": "Agoda — ดีที่สุดสำหรับเอเชียและไกลออกไป",
  "hotels.agoda_desc": "ราคาโรงแรมต่ำที่สุดอย่างสม่ำเสมอในเอเชีย อเมริกาใต้ และศูนย์กลางทั่วโลก มากกว่า 2 ล้านที่พักทั่วโลกพร้อมการยืนยันทันที",
  "hotels.agoda_cta": "ค้นหาดีลบน Agoda",
  "hotels.hotelscom_desc": "เหมาะสำหรับการเดินทางในอเมริกาเหนือและนโยบายยกเลิกที่ยืดหยุ่น รับหนึ่งคืนฟรีทุกๆ 10 คืนที่จอง",
