  "cars.title": "Horizon เช่ารถ",
  "cars.desc": "ข้ามการต่อคิวและค่าธรรมเนียมซ่อนเร้น เลือกพาร์ทเนอร์ที่ผ่านการตรวจสอบของเราเพื่อหายานพาหนะที่ดีที่สุดสำหรับการเดินทาง",
